CREATE OR REPLACE FUNCTION tests.visiter_staff(p_staff_id uuid, OUT staff_id uuid, OUT staff_history_id uuid) AS $$
BEGIN
    staff_id := COALESCE(p_staff_id, NULLIF(current_setting('jwt.claims.staff_id', true), '')::uuid);
    SELECT h.history_id INTO staff_history_id FROM tests.history_info_staff AS h
    WHERE h.info_staff_id = staff_id ORDER BY h.revision DESC, h.update_at DESC LIMIT 1;
    IF staff_history_id IS NULL THEN
        RAISE EXCEPTION '担当者が見つかりません (%)', staff_id USING ERRCODE = 'VIS00';
    END IF;
END
$$ LANGUAGE plpgsql STABLE;

COMMENT ON FUNCTION tests.visiter_staff(uuid) IS '@omit';

CREATE OR REPLACE FUNCTION tests.mrp_hist_staff(p_id uuid) RETURNS uuid AS $$
    SELECT h.history_id FROM tests.history_info_staff AS h
    WHERE h.info_staff_id = p_id ORDER BY h.revision DESC, h.update_at DESC LIMIT 1;
$$ LANGUAGE sql STABLE;

COMMENT ON FUNCTION tests.mrp_hist_staff(uuid) IS '@omit';

CREATE OR REPLACE FUNCTION tests.op_staff(p_staff_id uuid, OUT staff_id uuid, OUT staff_history_id uuid) AS $$
BEGIN
    staff_id := COALESCE(p_staff_id, NULLIF(current_setting('jwt.claims.staff_id', true), '')::uuid);
    SELECT h.history_id INTO staff_history_id FROM tests.history_info_staff AS h
    WHERE h.info_staff_id = staff_id ORDER BY h.revision DESC, h.update_at DESC LIMIT 1;
    IF staff_history_id IS NULL THEN
        RAISE EXCEPTION '担当者が見つかりません (%)', staff_id USING ERRCODE = 'OPR00';
    END IF;
END
$$ LANGUAGE plpgsql STABLE;

COMMENT ON FUNCTION tests.op_staff(uuid) IS '@omit';

