    SELECT h.history_id FROM tests.history_mstr_return_kind AS h
    WHERE h.mstr_return_kind_id = p_id ORDER BY h.revision DESC, h.update_at DESC LIMIT 1;
$$ LANGUAGE sql STABLE;

