CREATE VIEW tests.v_plan_change_unreflected AS
-- MRP 未反映の計画変更  claude/131
-- 受注明細・発注明細・生産計画の変更で、MRP の提案から作られたものでなく(trans_mrp_suggestion_id が NULL)、
-- まだ反映した MRP 実行が無いもの(reflected_trans_mrp_run_id が NULL)。
-- 生産計画の変更は、その生産計画の受注明細にも数える (受注明細一覧のバッジ用)
SELECT
    pc.trans_plan_change_id
    , pc.symbol
    , pc.change_at
    , COALESCE(pc.trans_order_detail_id, op_od.trans_order_detail_id) AS trans_order_detail_id
    , pc.trans_purchase_detail_id
    , pc.trans_operations_plan_id
    , pc.staff_id
FROM tests.trans_plan_change AS pc
LEFT JOIN LATERAL (
    SELECT rp.trans_order_detail_id FROM tests.trans_operations_plan AS op
    INNER JOIN tests.trans_resource_plan AS rp ON rp.trans_resource_plan_id = op.trans_resource_plan_id
    WHERE op.trans_operations_plan_id = pc.trans_operations_plan_id
) AS op_od ON TRUE
WHERE pc.remove IS FALSE
  AND pc.reflected_trans_mrp_run_id IS NULL
  AND pc.trans_mrp_suggestion_id IS NULL
  AND (pc.trans_order_detail_id IS NOT NULL OR pc.trans_purchase_detail_id IS NOT NULL OR pc.trans_operations_plan_id IS NOT NULL);

COMMENT ON VIEW tests.v_plan_change_unreflected IS '@primaryKey trans_plan_change_id
@unique symbol
@foreignKey (trans_plan_change_id) references trans_plan_change (trans_plan_change_id)
@foreignKey (trans_order_detail_id) references trans_order_detail (trans_order_detail_id)
@foreignKey (trans_purchase_detail_id) references trans_purchase_detail (trans_purchase_detail_id)
@foreignKey (trans_operations_plan_id) references trans_operations_plan (trans_operations_plan_id)
MRP未反映の計画変更';

CREATE VIEW tests.v_purchase_detail_balance AS
-- 発注明細の残 (MRP の供給の数え方)  claude/131
-- remaining_quantity : 数量 − キャンセル数量 − 受入済み ＋ 代品ありの返品(仕入先・外注先への返品)
-- open_quantity      : 停止中は 0
-- is_outsource       : 外注加工 (生産計画明細から参照される発注明細)。品目の供給ではない
-- 返品は入出庫判定区分マスタの receive = false (仕入先・外注先への返品) だけを数える
SELECT
    pd.trans_purchase_detail_id
    , pd.symbol
    , pd.trans_purchase_id
    , pd.item_id
    , pd.stop
    , pd.material_supply
    , pd.paid_supply
    , EXISTS (SELECT 1 FROM tests.trans_work_plan AS wp
              WHERE wp.trans_purchase_detail_id = pd.trans_purchase_detail_id AND wp.remove IS FALSE) AS is_outsource
    , COALESCE(pd.quantity, 0) AS quantity
    , pd.cancel_quantity
    , COALESCE(rc.q, 0) AS received_quantity
    , COALESCE(rt.q, 0) AS returned_quantity
    , COALESCE(rt.q_rep, 0) AS replacement_quantity
    , GREATEST(COALESCE(pd.quantity, 0) - pd.cancel_quantity - COALESCE(rc.q, 0) + COALESCE(rt.q_rep, 0), 0) AS remaining_quantity
    , CASE WHEN pd.stop THEN 0
           ELSE GREATEST(COALESCE(pd.quantity, 0) - pd.cancel_quantity - COALESCE(rc.q, 0) + COALESCE(rt.q_rep, 0), 0) END AS open_quantity
    , (pd.cancel_quantity > 0
       AND COALESCE(pd.quantity, 0) - pd.cancel_quantity - COALESCE(rc.q, 0) + COALESCE(rt.q_rep, 0) <= 0) AS cancel_closed
FROM tests.trans_purchase_detail AS pd
LEFT JOIN LATERAL (
    SELECT SUM(r.quantity) AS q FROM tests.trans_purchase_rec AS r
    WHERE r.trans_purchase_detail_id = pd.trans_purchase_detail_id AND r.remove IS FALSE
) AS rc ON TRUE
LEFT JOIN LATERAL (
    SELECT SUM(d.quantity) AS q, SUM(d.quantity) FILTER (WHERE d.replacement) AS q_rep
    FROM tests.trans_return_detail AS d
    INNER JOIN tests.trans_return AS h ON h.trans_return_id = d.trans_return_id AND h.remove IS FALSE
    INNER JOIN tests.mstr_return_kind AS k ON k.mstr_return_kind_id = h.return_kind_id AND k.receive IS FALSE
    WHERE d.trans_purchase_detail_id = pd.trans_purchase_detail_id AND d.remove IS FALSE
) AS rt ON TRUE
WHERE pd.remove IS FALSE;

COMMENT ON VIEW tests.v_purchase_detail_balance IS '@primaryKey trans_purchase_detail_id
@unique symbol
@foreignKey (trans_purchase_detail_id) references trans_purchase_detail (trans_purchase_detail_id)
@foreignKey (trans_purchase_id) references trans_purchase (trans_purchase_id)
@foreignKey (item_id) references mstr_item (mstr_item_id)
発注明細の残';

CREATE OR REPLACE FUNCTION tests.mrp_cancel_purchase_detail(p_pd uuid, p_suggestion uuid, p_run uuid,
                                                            p_staff uuid, p_staff_hist uuid, p_reason varchar)
RETURNS void AS $$
DECLARE v_old numeric; v_rem numeric; v_qty numeric;
BEGIN
    SELECT pd.cancel_quantity, b.remaining_quantity, b.quantity INTO v_old, v_rem, v_qty
    FROM tests.trans_purchase_detail AS pd
    INNER JOIN tests.v_purchase_detail_balance AS b ON b.trans_purchase_detail_id = pd.trans_purchase_detail_id
    WHERE pd.trans_purchase_detail_id = p_pd;
    IF NOT FOUND OR COALESCE(v_rem, 0) <= 0 THEN RETURN; END IF;
    UPDATE tests.trans_purchase_detail
    SET cancel_quantity = LEAST(COALESCE(cancel_quantity, 0) + v_rem, v_qty),
        update_user_id = p_staff, update_user_history_id = p_staff_hist
    WHERE trans_purchase_detail_id = p_pd;
    INSERT INTO tests.trans_plan_change (trans_purchase_detail_id, cancel_quantity, old_quantity, new_quantity, reason,
                                         staff_history_id, staff_id, trans_mrp_suggestion_id, reflected_trans_mrp_run_id,
                                         update_user_id, update_user_history_id)
    VALUES (p_pd, v_rem, v_qty, v_qty, p_reason, p_staff_hist, p_staff, p_suggestion, p_run, p_staff, p_staff_hist);
END
$$ LANGUAGE plpgsql VOLATILE;

COMMENT ON FUNCTION tests.mrp_cancel_purchase_detail(uuid, uuid, uuid, uuid, uuid, varchar) IS '@omit';

CREATE OR REPLACE FUNCTION tests.mrp_commit(
    p_run_id uuid,
    p_staff_id uuid DEFAULT NULL,
    p_force boolean DEFAULT false
) RETURNS tests.trans_mrp_run AS $$
DECLARE
    v_run tests.trans_mrp_run;
    v_staff uuid := tests.mrp_staff(p_staff_id);
    v_staff_hist uuid;
    r record; t record;
    v_rp uuid; v_op uuid; v_pd uuid; v_po uuid; v_wp uuid; v_parent_op uuid;
    v_pr uuid; v_prod uuid; v_n integer; v_rec numeric; v_qty numeric; v_dh numeric; v_ids uuid[];
BEGIN
    v_staff_hist := tests.mrp_hist_staff(v_staff);
    IF v_staff_hist IS NULL THEN
        RAISE EXCEPTION 'mrp_commit: 担当者が見つかりません (%)', v_staff USING ERRCODE = 'MRP00';
    END IF;
    PERFORM pg_advisory_xact_lock(hashtext('tests.mrp'));

    SELECT * INTO v_run FROM tests.trans_mrp_run WHERE trans_mrp_run_id = p_run_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'mrp_commit: MRP実行が見つかりません (%)', p_run_id USING ERRCODE = 'MRP03';
    END IF;
    IF v_run.status <> 0 THEN
        RAISE EXCEPTION 'mrp_commit: このMRP実行は確定できません (status=%)', v_run.status
            USING ERRCODE = 'MRP03', HINT = '新しく計算した実行があると、それより前の未確定の実行は失効します';
    END IF;

    -- 計算後の更新チェック
    IF NOT p_force AND (
           EXISTS (SELECT 1 FROM tests.trans_order WHERE update_at > v_run.run_at)
        OR EXISTS (SELECT 1 FROM tests.trans_order_detail WHERE update_at > v_run.run_at)
        OR EXISTS (SELECT 1 FROM tests.trans_unrecognized_detail WHERE update_at > v_run.run_at)
        OR EXISTS (SELECT 1 FROM tests.trans_purchase_detail WHERE update_at > v_run.run_at)
        OR EXISTS (SELECT 1 FROM tests.trans_purchase_rec WHERE update_at > v_run.run_at)
        OR EXISTS (SELECT 1 FROM tests.trans_operations_plan WHERE update_at > v_run.run_at)
        OR EXISTS (SELECT 1 FROM tests.trans_work_plan WHERE update_at > v_run.run_at)
        OR EXISTS (SELECT 1 FROM tests.trans_work_record WHERE update_at > v_run.run_at)
        OR EXISTS (SELECT 1 FROM tests.trans_resource_plan WHERE update_at > v_run.run_at)
        OR EXISTS (SELECT 1 FROM tests.trans_visiter WHERE update_at > v_run.run_at)
        OR EXISTS (SELECT 1 FROM tests.trans_complaint_visiter WHERE update_at > v_run.run_at)
        OR EXISTS (SELECT 1 FROM tests.mstr_item_lot WHERE update_at > v_run.run_at)
        OR EXISTS (SELECT 1 FROM tests.mstr_item_tree WHERE update_at > v_run.run_at)
        OR EXISTS (SELECT 1 FROM tests.mstr_item_operation_task WHERE update_at > v_run.run_at)
        OR EXISTS (SELECT 1 FROM tests.mstr_task_location WHERE update_at > v_run.run_at)
        OR EXISTS (SELECT 1 FROM tests.mstr_equipment_available WHERE update_at > v_run.run_at)
        OR EXISTS (SELECT 1 FROM tests.mstr_outsource_available WHERE update_at > v_run.run_at)
        OR EXISTS (SELECT 1 FROM tests.mstr_item_supplier WHERE update_at > v_run.run_at)
        -- claude/133: キャンセル・停止・返品・支給・所有
        OR EXISTS (SELECT 1 FROM tests.trans_plan_change WHERE update_at > v_run.run_at)
        OR EXISTS (SELECT 1 FROM tests.trans_return_detail WHERE update_at > v_run.run_at)
        OR EXISTS (SELECT 1 FROM tests.trans_supply WHERE update_at > v_run.run_at)
        OR EXISTS (SELECT 1 FROM tests.trans_supply_detail WHERE update_at > v_run.run_at)
        OR EXISTS (SELECT 1 FROM tests.trans_supply_visiter WHERE update_at > v_run.run_at)
        OR EXISTS (SELECT 1 FROM tests.trans_visiter_owner WHERE update_at > v_run.run_at)
    ) THEN
        RAISE EXCEPTION 'mrp_commit: MRP計算後にデータが更新されています。再計算してください'
            USING ERRCODE = 'MRP02';
    END IF;

    SELECT COUNT(*) INTO v_n FROM tests.trans_mrp_suggestion WHERE trans_mrp_run_id = p_run_id AND decision = 0;
    IF v_n > 0 AND NOT p_force THEN
        RAISE EXCEPTION 'mrp_commit: ユーザーの判断が必要な提案が % 件あります', v_n
            USING ERRCODE = 'MRP01', HINT = '採用か却下を選ぶか、p_force で要判断を却下として確定してください';
    END IF;

    DROP TABLE IF EXISTS _mrp_eff, _mrp_po;
    CREATE TEMP TABLE _mrp_eff ON COMMIT DROP AS
    WITH RECURSIVE e AS (
        SELECT s.trans_mrp_suggestion_id AS id FROM tests.trans_mrp_suggestion AS s
        WHERE s.trans_mrp_run_id = p_run_id AND s.parent_trans_mrp_suggestion_id IS NULL AND s.decision = 1
        UNION ALL
        SELECT s.trans_mrp_suggestion_id FROM tests.trans_mrp_suggestion AS s
        INNER JOIN e ON s.parent_trans_mrp_suggestion_id = e.id
        WHERE s.decision = 1
    )
    SELECT id FROM e;
    CREATE TEMP TABLE _mrp_po (stakeholder_id uuid, po_id uuid) ON COMMIT DROP;

    -- 引当をやり直す資材計画: 未引当(引当実績なし)の引当予約と購買/生産引当予約を取り消す
    UPDATE tests.trans_purchase_rez AS z SET remove = TRUE, update_user_id = v_staff, update_user_history_id = v_staff_hist
    FROM tests.trans_inventory_request AS rq
    INNER JOIN tests.trans_mrp_suggestion AS s
        ON s.trans_resource_plan_id = rq.trans_resource_plan_id AND s.trans_mrp_run_id = p_run_id
       AND s.kind IN ('PLAN_UPDATE', 'PLAN_KEEP', 'PLAN_CANCEL')
    INNER JOIN _mrp_eff AS e ON e.id = s.trans_mrp_suggestion_id
    WHERE z.trans_purchase_rez_id = rq.trans_purchase_rez_id AND rq.remove IS FALSE AND z.remove IS FALSE
      AND NOT EXISTS (SELECT 1 FROM tests.trans_inventory_apply AS ap
                      WHERE ap.trans_inventory_request_id = rq.trans_inventory_request_id AND ap.remove IS FALSE);
    UPDATE tests.trans_product_rez AS z SET remove = TRUE, update_user_id = v_staff, update_user_history_id = v_staff_hist
    FROM tests.trans_inventory_request AS rq
    INNER JOIN tests.trans_mrp_suggestion AS s
        ON s.trans_resource_plan_id = rq.trans_resource_plan_id AND s.trans_mrp_run_id = p_run_id
       AND s.kind IN ('PLAN_UPDATE', 'PLAN_KEEP', 'PLAN_CANCEL')
    INNER JOIN _mrp_eff AS e ON e.id = s.trans_mrp_suggestion_id
    WHERE z.trans_product_rez_id = rq.trans_product_rez_id AND rq.remove IS FALSE AND z.remove IS FALSE
      AND NOT EXISTS (SELECT 1 FROM tests.trans_inventory_apply AS ap
                      WHERE ap.trans_inventory_request_id = rq.trans_inventory_request_id AND ap.remove IS FALSE);
    UPDATE tests.trans_inventory_request AS rq SET remove = TRUE, update_user_id = v_staff, update_user_history_id = v_staff_hist
    FROM tests.trans_mrp_suggestion AS s
    INNER JOIN _mrp_eff AS e ON e.id = s.trans_mrp_suggestion_id
    WHERE s.trans_resource_plan_id = rq.trans_resource_plan_id AND s.trans_mrp_run_id = p_run_id
      AND s.kind IN ('PLAN_UPDATE', 'PLAN_KEEP', 'PLAN_CANCEL')
      AND rq.remove IS FALSE
      AND NOT EXISTS (SELECT 1 FROM tests.trans_inventory_apply AS ap
                      WHERE ap.trans_inventory_request_id = rq.trans_inventory_request_id AND ap.remove IS FALSE);

    -- 提案を順に反映 (seq 順 = 親が先)
    FOR r IN
        SELECT s.* FROM tests.trans_mrp_suggestion AS s
        INNER JOIN _mrp_eff AS e ON e.id = s.trans_mrp_suggestion_id
        ORDER BY s.seq
    LOOP
        CASE r.kind
        WHEN 'PLAN_NEW' THEN
            v_parent_op := COALESCE(r.parent_trans_operations_plan_id,
                (SELECT p.trans_operations_plan_id FROM tests.trans_mrp_suggestion AS p
                  WHERE p.trans_mrp_suggestion_id = r.parent_trans_mrp_suggestion_id AND p.kind = 'PRODUCTION_NEW'));
            INSERT INTO tests.trans_resource_plan (
                trans_order_detail_id, trans_unrecognized_detail_id, register_at, quantity, inventory_resavation,
                deadline, item_history_id, item_id, parent_trans_operations_plan_id,
                update_user_id, update_user_history_id)
            VALUES (
                r.trans_order_detail_id, r.trans_unrecognized_detail_id, now(), r.quantity, COALESCE(r.allocated_quantity, 0),
                r.need_at, r.item_history_id, r.item_id, v_parent_op,
                v_staff, v_staff_hist)
            RETURNING trans_resource_plan_id INTO v_rp;
            UPDATE tests.trans_mrp_suggestion SET trans_resource_plan_id = v_rp, parent_trans_operations_plan_id = v_parent_op,
                   applied_at = now() WHERE trans_mrp_suggestion_id = r.trans_mrp_suggestion_id;

        WHEN 'PLAN_UPDATE' THEN
            UPDATE tests.trans_resource_plan
            SET quantity = r.quantity, inventory_resavation = COALESCE(r.allocated_quantity, 0),
                deadline = CASE WHEN r.plan_kind = 3 THEN deadline ELSE r.need_at END,
                update_user_id = v_staff, update_user_history_id = v_staff_hist
            WHERE trans_resource_plan_id = r.trans_resource_plan_id;
            UPDATE tests.trans_mrp_suggestion SET applied_at = now() WHERE trans_mrp_suggestion_id = r.trans_mrp_suggestion_id;

        WHEN 'PLAN_CANCEL' THEN
            UPDATE tests.trans_resource_plan
            SET remove = TRUE, update_user_id = v_staff, update_user_history_id = v_staff_hist
            WHERE trans_resource_plan_id = r.trans_resource_plan_id;
            UPDATE tests.trans_mrp_suggestion SET applied_at = now() WHERE trans_mrp_suggestion_id = r.trans_mrp_suggestion_id;

        WHEN 'PURCHASE_NEW' THEN
            IF r.stakeholder_id IS NULL THEN
                RAISE EXCEPTION 'mrp_commit: 仕入先が未設定の発注提案があります (seq=%)', r.seq
                    USING ERRCODE = 'MRP04';
            END IF;
            SELECT p.trans_resource_plan_id INTO v_rp FROM tests.trans_mrp_suggestion AS p
            WHERE p.trans_mrp_suggestion_id = r.parent_trans_mrp_suggestion_id;
            SELECT po_id INTO v_po FROM _mrp_po WHERE stakeholder_id = r.stakeholder_id;
            IF v_po IS NULL THEN
                INSERT INTO tests.trans_purchase (
                    stakeholder_history_id, stakeholder_id, register_at, purchase_order_date, deadline, remarks,
                    update_user_id, update_user_history_id)
                VALUES (
                    COALESCE(tests.mrp_hist_stakeholder(r.stakeholder_id), r.stakeholder_history_id), r.stakeholder_id,
                    now(), r.release_at, r.due_at, 'MRP',
                    v_staff, v_staff_hist)
                RETURNING trans_purchase_id INTO v_po;
                INSERT INTO _mrp_po VALUES (r.stakeholder_id, v_po);
            ELSE
                UPDATE tests.trans_purchase
                SET purchase_order_date = LEAST(purchase_order_date, r.release_at), deadline = GREATEST(deadline, r.due_at)
                WHERE trans_purchase_id = v_po;
            END IF;
            INSERT INTO tests.trans_purchase_detail (
                trans_purchase_id, trans_resource_plan_id, restocking_purchase, quantity, unit_price, period,
                item_history_id, item_id, remarks, update_user_id, update_user_history_id)
            VALUES (
                v_po, v_rp, COALESCE(r.plan_kind = 3, false), r.quantity,
                CASE WHEN r.asking_price THEN 0 ELSE COALESCE(r.cost, 0) END, r.due_at,
                r.item_history_id, r.item_id,
                CONCAT_WS(' ', 'MRP', CASE WHEN r.asking_price THEN '言い値(単価未定)' END,
                          (SELECT '仕入先品番:' || ms.supplier_item_code FROM tests.mstr_item_supplier AS ms
                            WHERE ms.mstr_item_id = r.item_id AND ms.mstr_stakeholder_id = r.stakeholder_id
                              AND ms.remove IS FALSE AND ms.supplier_item_code IS NOT NULL LIMIT 1)),
                v_staff, v_staff_hist)
            RETURNING trans_purchase_detail_id INTO v_pd;
            UPDATE tests.trans_mrp_suggestion SET trans_purchase_detail_id = v_pd, applied_at = now()
            WHERE trans_mrp_suggestion_id = r.trans_mrp_suggestion_id;
            v_po := NULL;

        WHEN 'PURCHASE_RESCHEDULE' THEN
            UPDATE tests.trans_purchase_detail
            SET period = r.due_at, update_user_id = v_staff, update_user_history_id = v_staff_hist
            WHERE trans_purchase_detail_id = r.trans_purchase_detail_id;
            UPDATE tests.trans_mrp_suggestion SET applied_at = now() WHERE trans_mrp_suggestion_id = r.trans_mrp_suggestion_id;

        WHEN 'PURCHASE_CANCEL' THEN
            -- claude/133: 発注数量は書き換えず、残りをキャンセル数量にする (契約は消さない)。計画変更を記録
            PERFORM tests.mrp_cancel_purchase_detail(r.trans_purchase_detail_id, r.trans_mrp_suggestion_id, p_run_id, v_staff, v_staff_hist,
                                                     'MRP: 需要が無くなった発注の取消');
            UPDATE tests.trans_mrp_suggestion SET applied_at = now() WHERE trans_mrp_suggestion_id = r.trans_mrp_suggestion_id;

        WHEN 'PRODUCTION_NEW' THEN
            SELECT p.trans_resource_plan_id INTO v_rp FROM tests.trans_mrp_suggestion AS p
            WHERE p.trans_mrp_suggestion_id = r.parent_trans_mrp_suggestion_id;
            INSERT INTO tests.trans_operations_plan (
                trans_resource_plan_id, deadline, quantity, update_user_id, update_user_history_id)
            VALUES (v_rp, r.due_at, r.quantity, v_staff, v_staff_hist)
            RETURNING trans_operations_plan_id INTO v_op;
            FOR t IN
                SELECT * FROM tests.trans_mrp_suggestion_task
                WHERE trans_mrp_suggestion_id = r.trans_mrp_suggestion_id
                ORDER BY sequence, start_at
            LOOP
                INSERT INTO tests.trans_work_plan (
                    trans_operations_plan_id, mstr_task_id, sequence, interval_plan, start_at, completion_at,
                    mstr_equipment_available_history_id, mstr_equipment_available_id,
                    mstr_outsource_available_history_id, mstr_outsource_available_id,
                    update_user_id, update_user_history_id)
                VALUES (
                    v_op, t.mstr_task_id, t.sequence, t.interval_plan, t.start_at, t.completion_at,
                    t.mstr_equipment_available_history_id, t.mstr_equipment_available_id,
                    t.mstr_outsource_available_history_id, t.mstr_outsource_available_id,
                    v_staff, v_staff_hist)
                RETURNING trans_work_plan_id INTO v_wp;
                UPDATE tests.trans_mrp_suggestion_task SET trans_work_plan_id = v_wp
                WHERE trans_mrp_suggestion_task_id = t.trans_mrp_suggestion_task_id;
            END LOOP;
            UPDATE tests.trans_mrp_suggestion SET trans_operations_plan_id = v_op, trans_resource_plan_id = v_rp, applied_at = now()
            WHERE trans_mrp_suggestion_id = r.trans_mrp_suggestion_id;

        WHEN 'PRODUCTION_RESCHEDULE' THEN
            UPDATE tests.trans_work_plan AS wp
            SET start_at = t2.start_at, completion_at = t2.completion_at,
                mstr_equipment_available_id = CASE WHEN t2.mstr_equipment_available_id IS NOT NULL
                                                   THEN t2.mstr_equipment_available_id ELSE wp.mstr_equipment_available_id END,
                mstr_equipment_available_history_id = CASE WHEN t2.mstr_equipment_available_id IS NOT NULL
                                                   THEN t2.mstr_equipment_available_history_id ELSE wp.mstr_equipment_available_history_id END,
                interval_plan = COALESCE(t2.interval_plan, wp.interval_plan),
                update_user_id = v_staff, update_user_history_id = v_staff_hist
            FROM tests.trans_mrp_suggestion_task AS t2
            WHERE t2.trans_mrp_suggestion_id = r.trans_mrp_suggestion_id
              AND wp.trans_work_plan_id = t2.trans_work_plan_id;
            -- 外注発注済みの工程: 外注発注の納期 = その発注の最後の工程の完了 ＋ デリバリー時間
            UPDATE tests.trans_purchase_detail AS x
            SET period = y.last_end, update_user_id = v_staff, update_user_history_id = v_staff_hist
            FROM (SELECT wp.trans_purchase_detail_id,
                         MAX(wp.completion_at + COALESCE(oa.delivery_interval, INTERVAL '0')) AS last_end
                  FROM tests.trans_work_plan AS wp
                  LEFT JOIN tests.mstr_outsource_available AS oa
                      ON oa.mstr_outsource_available_id = wp.mstr_outsource_available_id
                  WHERE wp.trans_operations_plan_id = r.trans_operations_plan_id AND wp.remove IS FALSE
                    AND wp.mstr_outsource_available_id IS NOT NULL AND wp.trans_purchase_detail_id IS NOT NULL
                  GROUP BY wp.trans_purchase_detail_id) AS y
            WHERE x.trans_purchase_detail_id = y.trans_purchase_detail_id AND x.remove IS FALSE
              AND x.period IS DISTINCT FROM y.last_end;
            UPDATE tests.trans_operations_plan
            SET deadline = r.due_at, update_user_id = v_staff, update_user_history_id = v_staff_hist
            WHERE trans_operations_plan_id = r.trans_operations_plan_id;
            UPDATE tests.trans_mrp_suggestion SET applied_at = now() WHERE trans_mrp_suggestion_id = r.trans_mrp_suggestion_id;

        WHEN 'PRODUCTION_CANCEL' THEN
            IF EXISTS (SELECT 1 FROM tests.trans_work_record AS wr
                       INNER JOIN tests.trans_work_plan AS wp ON wp.trans_work_plan_id = wr.trans_work_plan_id
                       WHERE wp.trans_operations_plan_id = r.trans_operations_plan_id AND wr.remove IS FALSE) THEN
                -- 着手済み: 打ち切り (生産数量は書き換えない。仕掛品はキャンセル後の処置で扱う)  claude/133
                UPDATE tests.trans_operations_plan AS op
                SET discontinue = TRUE, update_user_id = v_staff, update_user_history_id = v_staff_hist
                WHERE op.trans_operations_plan_id = r.trans_operations_plan_id;
                INSERT INTO tests.trans_plan_change (trans_operations_plan_id, discontinue, reason, staff_history_id, staff_id,
                                                     trans_mrp_suggestion_id, reflected_trans_mrp_run_id,
                                                     update_user_id, update_user_history_id)
                VALUES (r.trans_operations_plan_id, TRUE, 'MRP: 需要が無くなった着手済みの生産の打ち切り', v_staff_hist, v_staff,
                        r.trans_mrp_suggestion_id, p_run_id, v_staff, v_staff_hist);
            ELSE
                -- 未入荷の外注発注も取り消す (キャンセル数量で記録)  claude/133
                FOR t IN
                    SELECT x.trans_purchase_detail_id FROM tests.trans_purchase_detail AS x
                    WHERE x.remove IS FALSE
                      AND x.trans_purchase_detail_id IN (
                          SELECT wp.trans_purchase_detail_id FROM tests.trans_work_plan AS wp
                          WHERE wp.trans_operations_plan_id = r.trans_operations_plan_id AND wp.remove IS FALSE)
                      AND NOT EXISTS (SELECT 1 FROM tests.trans_purchase_rec AS pr
                                      WHERE pr.trans_purchase_detail_id = x.trans_purchase_detail_id AND pr.remove IS FALSE)
                LOOP
                    PERFORM tests.mrp_cancel_purchase_detail(t.trans_purchase_detail_id, r.trans_mrp_suggestion_id, p_run_id,
                                                             v_staff, v_staff_hist, 'MRP: 取り消した生産の外注発注');
                END LOOP;
                INSERT INTO tests.trans_plan_change (trans_operations_plan_id, discontinue, reason, staff_history_id, staff_id,
                                                     trans_mrp_suggestion_id, reflected_trans_mrp_run_id,
                                                     update_user_id, update_user_history_id)
                VALUES (r.trans_operations_plan_id, TRUE, 'MRP: 需要が無くなった未着手の生産の取消', v_staff_hist, v_staff,
                        r.trans_mrp_suggestion_id, p_run_id, v_staff, v_staff_hist);
                UPDATE tests.trans_work_plan SET remove = TRUE, update_user_id = v_staff, update_user_history_id = v_staff_hist
                WHERE trans_operations_plan_id = r.trans_operations_plan_id AND remove IS FALSE;
                UPDATE tests.trans_operations_plan SET remove = TRUE, update_user_id = v_staff, update_user_history_id = v_staff_hist
                WHERE trans_operations_plan_id = r.trans_operations_plan_id;
            END IF;
            UPDATE tests.trans_mrp_suggestion SET applied_at = now() WHERE trans_mrp_suggestion_id = r.trans_mrp_suggestion_id;

        WHEN 'OUTSOURCE_NEW', 'OUTSOURCE_OPTION' THEN
            IF r.stakeholder_id IS NULL THEN
                RAISE EXCEPTION 'mrp_commit: 外注先が未設定の外注発注提案があります (seq=%)', r.seq
                    USING ERRCODE = 'MRP04';
            END IF;
            -- 対象の生産計画
            v_op := COALESCE(r.trans_operations_plan_id,
                (SELECT p.trans_operations_plan_id FROM tests.trans_mrp_suggestion AS p
                  WHERE p.trans_mrp_suggestion_id = r.parent_trans_mrp_suggestion_id));
            SELECT op.trans_resource_plan_id, COALESCE(NULLIF(op.quantity, 0), r.quantity) INTO v_rp, v_qty
            FROM tests.trans_operations_plan AS op WHERE op.trans_operations_plan_id = v_op;
            IF r.kind = 'OUTSOURCE_OPTION' THEN
                -- 内部で計画した工程を外部に切り替える (日程はそのまま。次の再MRPで見直す)
                SELECT EXTRACT(EPOCH FROM COALESCE(oa.delivery_interval, INTERVAL '0')) / 3600 INTO v_dh
                FROM tests.mstr_outsource_available AS oa WHERE oa.mstr_outsource_available_id = r.mstr_outsource_available_id;
                UPDATE tests.trans_mrp_suggestion_task AS tk
                SET mstr_equipment_available_id = NULL, mstr_equipment_available_history_id = NULL,
                    mstr_outsource_available_id = r.mstr_outsource_available_id,
                    mstr_outsource_available_history_id = r.mstr_outsource_available_history_id,
                    outsource_trans_mrp_suggestion_id = r.trans_mrp_suggestion_id, cost = r.cost
                WHERE tk.trans_mrp_suggestion_task_id = r.trans_mrp_suggestion_task_id
                RETURNING tk.trans_work_plan_id INTO v_wp;
                CONTINUE WHEN v_wp IS NULL;
                UPDATE tests.trans_work_plan
                SET mstr_equipment_available_id = NULL, mstr_equipment_available_history_id = NULL,
                    mstr_outsource_available_id = r.mstr_outsource_available_id,
                    mstr_outsource_available_history_id = r.mstr_outsource_available_history_id,
                    update_user_id = v_staff, update_user_history_id = v_staff_hist
                WHERE trans_work_plan_id = v_wp;
                SELECT wp.start_at, wp.completion_at + make_interval(secs => (COALESCE(v_dh, 0) * 3600)::double precision)
                INTO r.release_at, r.due_at FROM tests.trans_work_plan AS wp WHERE wp.trans_work_plan_id = v_wp;
            END IF;
            SELECT po_id INTO v_po FROM _mrp_po WHERE stakeholder_id = r.stakeholder_id;
            IF v_po IS NULL THEN
                INSERT INTO tests.trans_purchase (
                    stakeholder_history_id, stakeholder_id, register_at, purchase_order_date, deadline, remarks,
                    update_user_id, update_user_history_id)
                VALUES (
                    COALESCE(tests.mrp_hist_stakeholder(r.stakeholder_id), r.stakeholder_history_id), r.stakeholder_id,
                    now(), r.release_at, r.due_at, 'MRP', v_staff, v_staff_hist)
                RETURNING trans_purchase_id INTO v_po;
                INSERT INTO _mrp_po VALUES (r.stakeholder_id, v_po);
            ELSE
                UPDATE tests.trans_purchase
                SET purchase_order_date = LEAST(purchase_order_date, r.release_at), deadline = GREATEST(deadline, r.due_at)
                WHERE trans_purchase_id = v_po;
            END IF;
            INSERT INTO tests.trans_purchase_detail (
                trans_purchase_id, trans_resource_plan_id, restocking_purchase, quantity, unit_price, period,
                material_supply, paid_supply,
                item_history_id, item_id, remarks, update_user_id, update_user_history_id)
            VALUES (
                v_po, v_rp, FALSE, v_qty, COALESCE(r.cost, 0), r.due_at,
                -- 資材支給区分・有償支給区分: 対象の工程の利用可能外部から
                COALESCE((SELECT BOOL_OR(oa.material_supply) FROM tests.trans_mrp_suggestion_task AS tk
                          INNER JOIN tests.mstr_outsource_available AS oa
                              ON oa.mstr_outsource_available_id = COALESCE(tk.mstr_outsource_available_id, r.mstr_outsource_available_id)
                          WHERE tk.trans_mrp_suggestion_id = r.trans_mrp_suggestion_id
                             OR tk.outsource_trans_mrp_suggestion_id = r.trans_mrp_suggestion_id
                             OR tk.trans_mrp_suggestion_task_id = r.trans_mrp_suggestion_task_id), FALSE),
                COALESCE((SELECT BOOL_OR(oa.paid_supply) FROM tests.trans_mrp_suggestion_task AS tk
                          INNER JOIN tests.mstr_outsource_available AS oa
                              ON oa.mstr_outsource_available_id = COALESCE(tk.mstr_outsource_available_id, r.mstr_outsource_available_id)
                          WHERE tk.trans_mrp_suggestion_id = r.trans_mrp_suggestion_id
                             OR tk.outsource_trans_mrp_suggestion_id = r.trans_mrp_suggestion_id
                             OR tk.trans_mrp_suggestion_task_id = r.trans_mrp_suggestion_task_id), FALSE),
                r.item_history_id, r.item_id, 'MRP 外注加工', v_staff, v_staff_hist)
            RETURNING trans_purchase_detail_id INTO v_pd;
            -- 対象の生産計画明細に外注発注明細を付ける (外注発注明細から参照される = 外注加工)
            UPDATE tests.trans_work_plan AS wp
            SET trans_purchase_detail_id = v_pd, update_user_id = v_staff, update_user_history_id = v_staff_hist
            WHERE wp.trans_work_plan_id IN (
                SELECT tk.trans_work_plan_id FROM tests.trans_mrp_suggestion_task AS tk
                WHERE (tk.trans_mrp_suggestion_id = r.trans_mrp_suggestion_id
                       OR tk.outsource_trans_mrp_suggestion_id = r.trans_mrp_suggestion_id)
                  AND tk.trans_work_plan_id IS NOT NULL);
            UPDATE tests.trans_mrp_suggestion SET trans_purchase_detail_id = v_pd, trans_operations_plan_id = v_op,
                   trans_resource_plan_id = v_rp, applied_at = now()
            WHERE trans_mrp_suggestion_id = r.trans_mrp_suggestion_id;
            v_po := NULL;

        WHEN 'OUTSOURCE_CANCEL' THEN
            -- claude/133: 発注数量は書き換えず、残りをキャンセル数量にする。未入荷なら工程計画からも外す
            SELECT COALESCE(SUM(quantity), 0) INTO v_rec FROM tests.trans_purchase_rec
            WHERE trans_purchase_detail_id = r.trans_purchase_detail_id AND remove IS FALSE;
            PERFORM tests.mrp_cancel_purchase_detail(r.trans_purchase_detail_id, r.trans_mrp_suggestion_id, p_run_id, v_staff, v_staff_hist,
                                                     'MRP: 内部に戻した工程の外注発注の取消');
            IF v_rec = 0 THEN
                UPDATE tests.trans_work_plan SET trans_purchase_detail_id = NULL, update_user_id = v_staff, update_user_history_id = v_staff_hist
                WHERE trans_purchase_detail_id = r.trans_purchase_detail_id;
            END IF;
            UPDATE tests.trans_mrp_suggestion SET applied_at = now() WHERE trans_mrp_suggestion_id = r.trans_mrp_suggestion_id;

        ELSE
            NULL;   -- PLAN_KEEP / EXC_* は反映なし
        END CASE;
    END LOOP;

    -- ペギング → 引当予約 (在庫: 予約のみ / 発注: 購買引当予約 / 生産: 最終工程の生産引当予約)
    FOR r IN
        SELECT pg.*, ds.trans_resource_plan_id AS rp_id,
               ss.trans_purchase_detail_id AS new_pd, ss.trans_operations_plan_id AS new_op,
               (pg.supply_trans_mrp_suggestion_id IS NULL OR es.id IS NOT NULL) AS supply_ok
        FROM tests.trans_mrp_pegging AS pg
        INNER JOIN tests.trans_mrp_suggestion AS ds
            ON ds.trans_mrp_suggestion_id = pg.demand_trans_mrp_suggestion_id
        INNER JOIN _mrp_eff AS ed ON ed.id = ds.trans_mrp_suggestion_id
        LEFT JOIN tests.trans_mrp_suggestion AS ss
            ON ss.trans_mrp_suggestion_id = pg.supply_trans_mrp_suggestion_id
        LEFT JOIN _mrp_eff AS es ON es.id = pg.supply_trans_mrp_suggestion_id
        WHERE pg.trans_mrp_run_id = p_run_id AND pg.quantity > 0 AND pg.remove IS FALSE
          AND ds.kind IN ('PLAN_NEW', 'PLAN_UPDATE', 'PLAN_KEEP')
    LOOP
        CONTINUE WHEN NOT r.supply_ok OR r.rp_id IS NULL;
        -- 顧客支給 (claude/133): 支給明細を充てる資材計画につなぐ。支給予定(6)は引当予約を作らない
        IF r.trans_supply_detail_id IS NOT NULL THEN
            UPDATE tests.trans_supply_detail
            SET trans_resource_plan_id = r.rp_id, update_user_id = v_staff, update_user_history_id = v_staff_hist
            WHERE trans_supply_detail_id = r.trans_supply_detail_id AND trans_resource_plan_id IS NULL;
        END IF;
        CONTINUE WHEN r.supply_kind = 6;
        v_pr := NULL; v_prod := NULL;
        -- 元の資材計画が取消済みの既存供給は、新しい需要に付け替える
        IF r.supply_kind = 2 THEN
            UPDATE tests.trans_purchase_detail AS x SET trans_resource_plan_id = r.rp_id,
                   update_user_id = v_staff, update_user_history_id = v_staff_hist
            WHERE x.trans_purchase_detail_id = r.trans_purchase_detail_id AND x.restocking_purchase IS NOT TRUE
              AND (x.trans_resource_plan_id IS NULL OR NOT EXISTS (
                   SELECT 1 FROM tests.trans_resource_plan AS y
                   WHERE y.trans_resource_plan_id = x.trans_resource_plan_id AND y.remove IS FALSE));
        ELSIF r.supply_kind = 3 THEN
            UPDATE tests.trans_operations_plan AS x SET trans_resource_plan_id = r.rp_id,
                   update_user_id = v_staff, update_user_history_id = v_staff_hist
            WHERE x.trans_operations_plan_id = r.trans_operations_plan_id
              AND NOT EXISTS (
                   SELECT 1 FROM tests.trans_resource_plan AS y
                   WHERE y.trans_resource_plan_id = x.trans_resource_plan_id AND y.remove IS FALSE);
        END IF;
        IF r.supply_kind IN (2, 4) THEN
            v_pd := COALESCE(r.trans_purchase_detail_id, r.new_pd);
            CONTINUE WHEN v_pd IS NULL;
            INSERT INTO tests.trans_purchase_rez (trans_purchase_detail_id, update_user_id, update_user_history_id)
            VALUES (v_pd, v_staff, v_staff_hist)
            RETURNING trans_purchase_rez_id INTO v_pr;
        ELSIF r.supply_kind IN (3, 5) THEN
            v_op := COALESCE(r.trans_operations_plan_id, r.new_op);
            v_wp := NULL;
            SELECT wp.trans_work_plan_id INTO v_wp FROM tests.trans_work_plan AS wp
            WHERE wp.trans_operations_plan_id = v_op AND wp.remove IS FALSE
            ORDER BY wp.sequence DESC NULLS LAST, wp.completion_at DESC NULLS LAST LIMIT 1;
            IF v_wp IS NOT NULL THEN
                INSERT INTO tests.trans_product_rez (trans_work_plan_id, update_user_id, update_user_history_id)
                VALUES (v_wp, v_staff, v_staff_hist)
                RETURNING trans_product_rez_id INTO v_prod;
            END IF;
        END IF;
        INSERT INTO tests.trans_inventory_request (
            register_at, register_plan_at, trans_purchase_rez_id, trans_product_rez_id, quantity,
            staff_history_id, staff_id, trans_resource_plan_id, update_user_id, update_user_history_id)
        VALUES (
            now(), COALESCE(r.need_at, now()), v_pr, v_prod, r.quantity,
            v_staff_hist, v_staff, r.rp_id, v_staff, v_staff_hist);
    END LOOP;

    -- 反映した計画変更 (claude/133): 再MRPで、計算より前に登録された未反映の計画変更
    --   範囲指定なら、その受注明細(生産計画の変更はその受注明細)の分だけ。受注MRPは既存の計画を凍結するので反映しない
    IF v_run.run_mode = 2 THEN
        SELECT array_agg(x::uuid) INTO v_ids
        FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_run.params->'order_detail_ids') = 'array'
                                            THEN v_run.params->'order_detail_ids' END) AS x;
        UPDATE tests.trans_plan_change AS pc
        SET reflected_trans_mrp_run_id = p_run_id, update_user_id = v_staff, update_user_history_id = v_staff_hist
        FROM tests.v_plan_change_unreflected AS u
        WHERE u.trans_plan_change_id = pc.trans_plan_change_id AND u.change_at <= v_run.run_at
          AND (v_ids IS NULL OR u.trans_order_detail_id = ANY (v_ids));
    END IF;

    UPDATE tests.trans_mrp_run
    SET status = 1, committed_at = now(), update_user_id = v_staff, update_user_history_id = v_staff_hist
    WHERE trans_mrp_run_id = p_run_id;
    SELECT * INTO v_run FROM tests.trans_mrp_run WHERE trans_mrp_run_id = p_run_id;
    RETURN v_run;
END
$$ LANGUAGE plpgsql VOLATILE;

COMMENT ON FUNCTION tests.mrp_commit(uuid, uuid, boolean) IS 'MRP確定。採用(decision=1)された提案を資材計画・発注・生産計画・引当予約に反映する。';

CREATE OR REPLACE FUNCTION tests.purchase_detail_cancel(
    p_purchase_detail_id uuid,
    p_quantity numeric,
    p_change_reason_id uuid DEFAULT NULL,
    p_reason varchar DEFAULT NULL,
    p_stakeholder_id uuid DEFAULT NULL,
    p_staff_id uuid DEFAULT NULL,
    p_parent_plan_change_id uuid DEFAULT NULL,
    p_remarks varchar DEFAULT NULL
) RETURNS tests.trans_plan_change AS $$
DECLARE
    v_st record; v_pd tests.trans_purchase_detail; v_remaining numeric;
BEGIN
    SELECT * INTO v_st FROM tests.op_staff(p_staff_id);
    SELECT * INTO v_pd FROM tests.trans_purchase_detail WHERE trans_purchase_detail_id = p_purchase_detail_id AND remove IS FALSE FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION '発注明細が見つかりません (%)', p_purchase_detail_id USING ERRCODE = 'OPR01';
    END IF;
    SELECT b.remaining_quantity INTO v_remaining FROM tests.v_purchase_detail_balance AS b
    WHERE b.trans_purchase_detail_id = p_purchase_detail_id;
    IF p_quantity IS NULL OR p_quantity <= 0 OR p_quantity > COALESCE(v_remaining, 0) THEN
        RAISE EXCEPTION 'キャンセルできる数量は 0 より大きく、残(%)以下です: %', COALESCE(v_remaining, 0), p_quantity
            USING ERRCODE = 'OPR02';
    END IF;
    UPDATE tests.trans_purchase_detail
    SET cancel_quantity = cancel_quantity + p_quantity, update_user_id = v_st.staff_id, update_user_history_id = v_st.staff_history_id
    WHERE trans_purchase_detail_id = p_purchase_detail_id;
    RETURN tests.op_add_plan_change(v_st.staff_id, v_st.staff_history_id, p_purchase_detail => p_purchase_detail_id,
        p_old_quantity => v_pd.quantity, p_new_quantity => v_pd.quantity, p_cancel_quantity => p_quantity,
        p_change_reason_id => p_change_reason_id, p_reason => p_reason, p_stakeholder_id => p_stakeholder_id,
        p_parent => p_parent_plan_change_id, p_remarks => p_remarks);
END
$$ LANGUAGE plpgsql VOLATILE;

COMMENT ON FUNCTION tests.purchase_detail_cancel(uuid, numeric, uuid, varchar, uuid, uuid, uuid, varchar) IS '発注明細のキャンセル(一部・全部)。キャンセル数量を加算し、計画変更を記録する(1トランザクション)。戻り値は計画変更';

CREATE OR REPLACE FUNCTION tests.purchase_detail_set_stop(
    p_purchase_detail_id uuid,
    p_stop boolean,
    p_change_reason_id uuid DEFAULT NULL,
    p_reason varchar DEFAULT NULL,
    p_stakeholder_id uuid DEFAULT NULL,
    p_staff_id uuid DEFAULT NULL,
    p_parent_plan_change_id uuid DEFAULT NULL,
    p_remarks varchar DEFAULT NULL
) RETURNS tests.trans_plan_change AS $$
DECLARE
    v_st record; v_pd tests.trans_purchase_detail;
BEGIN
    SELECT * INTO v_st FROM tests.op_staff(p_staff_id);
    SELECT * INTO v_pd FROM tests.trans_purchase_detail WHERE trans_purchase_detail_id = p_purchase_detail_id AND remove IS FALSE FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION '発注明細が見つかりません (%)', p_purchase_detail_id USING ERRCODE = 'OPR01';
    END IF;
    IF p_stop IS NULL OR COALESCE(v_pd.stop, false) = p_stop THEN
        RAISE EXCEPTION '停止の状態が、すでに同じです (stop = %)', COALESCE(v_pd.stop, false) USING ERRCODE = 'OPR03';
    END IF;
    IF p_stop AND EXISTS (SELECT 1 FROM tests.v_purchase_detail_balance AS b WHERE b.trans_purchase_detail_id = p_purchase_detail_id AND b.cancel_closed) THEN
        RAISE EXCEPTION '全部キャンセル済みの発注明細は停止できません' USING ERRCODE = 'OPR03';
    END IF;
    UPDATE tests.trans_purchase_detail
    SET stop = p_stop, update_user_id = v_st.staff_id, update_user_history_id = v_st.staff_history_id
    WHERE trans_purchase_detail_id = p_purchase_detail_id;
    RETURN tests.op_add_plan_change(v_st.staff_id, v_st.staff_history_id, p_purchase_detail => p_purchase_detail_id,
        p_old_stop => COALESCE(v_pd.stop, false), p_new_stop => p_stop,
        p_change_reason_id => p_change_reason_id, p_reason => p_reason, p_stakeholder_id => p_stakeholder_id,
        p_parent => p_parent_plan_change_id, p_remarks => p_remarks);
END
$$ LANGUAGE plpgsql VOLATILE;

COMMENT ON FUNCTION tests.purchase_detail_set_stop(uuid, boolean, uuid, varchar, uuid, uuid, uuid, varchar) IS '発注明細の停止・再開。計画変更(旧・新の停止)を記録する(1トランザクション)。戻り値は計画変更';

CREATE OR REPLACE FUNCTION tests.purchase_detail_change(
    p_purchase_detail_id uuid,
    p_new_quantity numeric DEFAULT NULL,
    p_new_period timestamp DEFAULT NULL,
    p_change_reason_id uuid DEFAULT NULL,
    p_reason varchar DEFAULT NULL,
    p_stakeholder_id uuid DEFAULT NULL,
    p_staff_id uuid DEFAULT NULL,
    p_parent_plan_change_id uuid DEFAULT NULL,
    p_remarks varchar DEFAULT NULL
) RETURNS tests.trans_plan_change AS $$
DECLARE
    v_st record; v_pd tests.trans_purchase_detail; v_received numeric;
BEGIN
    SELECT * INTO v_st FROM tests.op_staff(p_staff_id);
    IF p_new_quantity IS NULL AND p_new_period IS NULL THEN
        RAISE EXCEPTION '新しい数量または納期のどちらかは必須です' USING ERRCODE = 'OPR02';
    END IF;
    SELECT * INTO v_pd FROM tests.trans_purchase_detail WHERE trans_purchase_detail_id = p_purchase_detail_id AND remove IS FALSE FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION '発注明細が見つかりません (%)', p_purchase_detail_id USING ERRCODE = 'OPR01';
    END IF;
    IF p_new_quantity IS NOT NULL THEN
        SELECT COALESCE(b.received_quantity, 0) INTO v_received FROM tests.v_purchase_detail_balance AS b
        WHERE b.trans_purchase_detail_id = p_purchase_detail_id;
        v_received := COALESCE(v_received, 0);
        IF p_new_quantity <= 0 OR p_new_quantity < v_pd.cancel_quantity + v_received THEN
            RAISE EXCEPTION '数量は 0 より大きく、キャンセル数量(%)と受入済み(%)の合計以上にしてください: %',
                v_pd.cancel_quantity, v_received, p_new_quantity USING ERRCODE = 'OPR02';
        END IF;
    END IF;
    UPDATE tests.trans_purchase_detail
    SET quantity = COALESCE(p_new_quantity, quantity), period = COALESCE(p_new_period, period),
        update_user_id = v_st.staff_id, update_user_history_id = v_st.staff_history_id
    WHERE trans_purchase_detail_id = p_purchase_detail_id;
    RETURN tests.op_add_plan_change(v_st.staff_id, v_st.staff_history_id, p_purchase_detail => p_purchase_detail_id,
        p_old_quantity => CASE WHEN p_new_quantity IS NULL THEN NULL ELSE v_pd.quantity END, p_new_quantity => p_new_quantity,
        p_old_date => CASE WHEN p_new_period IS NULL THEN NULL ELSE v_pd.period END, p_new_date => p_new_period,
        p_change_reason_id => p_change_reason_id, p_reason => p_reason, p_stakeholder_id => p_stakeholder_id,
        p_parent => p_parent_plan_change_id, p_remarks => p_remarks);
END
$$ LANGUAGE plpgsql VOLATILE;

COMMENT ON FUNCTION tests.purchase_detail_change(uuid, numeric, timestamp, uuid, varchar, uuid, uuid, uuid, varchar) IS '発注明細の納期・数量の変更。本体を更新し、計画変更(旧・新)を記録する(1トランザクション)。戻り値は計画変更';

CREATE VIEW tests.v_order_detail_balance AS
-- 受注明細の残 (MRP の需要の数え方)  claude/131
-- remaining_quantity : 数量 − キャンセル数量 − 出荷済み ＋ 代品ありの返品
-- open_quantity      : 停止中は 0 (MRP は停止中の受注明細を凍結する)
-- cancel_closed      : キャンセル数量 > 0 かつ 残 0 (全部キャンセル済み)
-- settlement_amount  : 途中精算の合計 (受注金額に加える。精算1件 = 請求書1行)
-- 返品は入出庫判定区分マスタの receive = true (顧客からの返品) だけを数える
SELECT
    od.trans_order_detail_id
    , od.symbol
    , od.trans_order_id
    , od.item_id
    , od.stop
    , od.customer_property
    , od.quantity
    , od.cancel_quantity
    , COALESCE(sh.q, 0) AS shipped_quantity
    , COALESCE(rt.q, 0) AS returned_quantity
    , COALESCE(rt.q_rep, 0) AS replacement_quantity
    , GREATEST(od.quantity - od.cancel_quantity - COALESCE(sh.q, 0) + COALESCE(rt.q_rep, 0), 0) AS remaining_quantity
    , CASE WHEN od.stop THEN 0
           ELSE GREATEST(od.quantity - od.cancel_quantity - COALESCE(sh.q, 0) + COALESCE(rt.q_rep, 0), 0) END AS open_quantity
    , (od.cancel_quantity > 0
       AND od.quantity - od.cancel_quantity - COALESCE(sh.q, 0) + COALESCE(rt.q_rep, 0) <= 0) AS cancel_closed
    , COALESCE(st.amount, 0) AS settlement_amount
FROM tests.trans_order_detail AS od
LEFT JOIN LATERAL (
    SELECT SUM(r.shipping_quantity) AS q
    FROM tests.trans_shipping_order_detail AS sd
    INNER JOIN tests.trans_shipping_order_detail_record AS r
        ON r.trans_shipping_order_detail_id = sd.trans_shipping_order_detail_id AND r.remove IS FALSE
    WHERE sd.trans_order_detail_id = od.trans_order_detail_id AND sd.remove IS FALSE
) AS sh ON TRUE
LEFT JOIN LATERAL (
    SELECT SUM(d.quantity) AS q, SUM(d.quantity) FILTER (WHERE d.replacement) AS q_rep
    FROM tests.trans_return_detail AS d
    INNER JOIN tests.trans_return AS h ON h.trans_return_id = d.trans_return_id AND h.remove IS FALSE
    INNER JOIN tests.mstr_return_kind AS k ON k.mstr_return_kind_id = h.return_kind_id AND k.receive IS TRUE
    WHERE d.trans_order_detail_id = od.trans_order_detail_id AND d.remove IS FALSE
) AS rt ON TRUE
LEFT JOIN LATERAL (
    SELECT SUM(s.amount) AS amount FROM tests.trans_order_detail_settlement AS s
    WHERE s.trans_order_detail_id = od.trans_order_detail_id AND s.remove IS FALSE
) AS st ON TRUE
WHERE od.remove IS FALSE;

COMMENT ON VIEW tests.v_order_detail_balance IS '@primaryKey trans_order_detail_id
@unique symbol
@foreignKey (trans_order_detail_id) references trans_order_detail (trans_order_detail_id)
@foreignKey (trans_order_id) references trans_order (trans_order_id)
@foreignKey (item_id) references mstr_item (mstr_item_id)
受注明細の残';

CREATE OR REPLACE FUNCTION tests.order_detail_cancel(
    p_order_detail_id uuid,
    p_quantity numeric,
    p_change_reason_id uuid DEFAULT NULL,
    p_reason varchar DEFAULT NULL,
    p_stakeholder_id uuid DEFAULT NULL,
    p_staff_id uuid DEFAULT NULL,
    p_parent_plan_change_id uuid DEFAULT NULL,
    p_remarks varchar DEFAULT NULL
) RETURNS tests.trans_plan_change AS $$
DECLARE
    v_st record; v_od tests.trans_order_detail; v_remaining numeric;
BEGIN
    SELECT * INTO v_st FROM tests.op_staff(p_staff_id);
    SELECT * INTO v_od FROM tests.trans_order_detail WHERE trans_order_detail_id = p_order_detail_id AND remove IS FALSE FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION '受注明細が見つかりません (%)', p_order_detail_id USING ERRCODE = 'OPR01';
    END IF;
    SELECT b.remaining_quantity INTO v_remaining FROM tests.v_order_detail_balance AS b
    WHERE b.trans_order_detail_id = p_order_detail_id;
    IF p_quantity IS NULL OR p_quantity <= 0 OR p_quantity > COALESCE(v_remaining, 0) THEN
        RAISE EXCEPTION 'キャンセルできる数量は 0 より大きく、残(%)以下です: %', COALESCE(v_remaining, 0), p_quantity
            USING ERRCODE = 'OPR02';
    END IF;
    UPDATE tests.trans_order_detail
    SET cancel_quantity = cancel_quantity + p_quantity, update_user_id = v_st.staff_id, update_user_history_id = v_st.staff_history_id
    WHERE trans_order_detail_id = p_order_detail_id;
    RETURN tests.op_add_plan_change(v_st.staff_id, v_st.staff_history_id, p_order_detail => p_order_detail_id,
        p_old_quantity => v_od.quantity, p_new_quantity => v_od.quantity, p_cancel_quantity => p_quantity,
        p_change_reason_id => p_change_reason_id, p_reason => p_reason, p_stakeholder_id => p_stakeholder_id,
        p_parent => p_parent_plan_change_id, p_remarks => p_remarks);
END
$$ LANGUAGE plpgsql VOLATILE;

COMMENT ON FUNCTION tests.order_detail_cancel(uuid, numeric, uuid, varchar, uuid, uuid, uuid, varchar) IS '受注明細のキャンセル(一部・全部)。キャンセル数量を加算し、計画変更を記録する(1トランザクション)。戻り値は計画変更';

CREATE OR REPLACE FUNCTION tests.order_detail_set_stop(
    p_order_detail_id uuid,
    p_stop boolean,
    p_change_reason_id uuid DEFAULT NULL,
    p_reason varchar DEFAULT NULL,
    p_stakeholder_id uuid DEFAULT NULL,
    p_staff_id uuid DEFAULT NULL,
    p_parent_plan_change_id uuid DEFAULT NULL,
    p_remarks varchar DEFAULT NULL
) RETURNS tests.trans_plan_change AS $$
DECLARE
    v_st record; v_od tests.trans_order_detail;
BEGIN
    SELECT * INTO v_st FROM tests.op_staff(p_staff_id);
    SELECT * INTO v_od FROM tests.trans_order_detail WHERE trans_order_detail_id = p_order_detail_id AND remove IS FALSE FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION '受注明細が見つかりません (%)', p_order_detail_id USING ERRCODE = 'OPR01';
    END IF;
    IF p_stop IS NULL OR COALESCE(v_od.stop, false) = p_stop THEN
        RAISE EXCEPTION '停止の状態が、すでに同じです (stop = %)', COALESCE(v_od.stop, false) USING ERRCODE = 'OPR03';
    END IF;
    IF p_stop AND EXISTS (SELECT 1 FROM tests.v_order_detail_balance AS b WHERE b.trans_order_detail_id = p_order_detail_id AND b.cancel_closed) THEN
        RAISE EXCEPTION '全部キャンセル済みの受注明細は停止できません' USING ERRCODE = 'OPR03';
    END IF;
    UPDATE tests.trans_order_detail
    SET stop = p_stop, update_user_id = v_st.staff_id, update_user_history_id = v_st.staff_history_id
    WHERE trans_order_detail_id = p_order_detail_id;
    RETURN tests.op_add_plan_change(v_st.staff_id, v_st.staff_history_id, p_order_detail => p_order_detail_id,
        p_old_stop => COALESCE(v_od.stop, false), p_new_stop => p_stop,
        p_change_reason_id => p_change_reason_id, p_reason => p_reason, p_stakeholder_id => p_stakeholder_id,
        p_parent => p_parent_plan_change_id, p_remarks => p_remarks);
END
$$ LANGUAGE plpgsql VOLATILE;

COMMENT ON FUNCTION tests.order_detail_set_stop(uuid, boolean, uuid, varchar, uuid, uuid, uuid, varchar) IS '受注明細の停止・再開。計画変更(旧・新の停止)を記録する(1トランザクション)。戻り値は計画変更';

CREATE OR REPLACE FUNCTION tests.order_detail_change(
    p_order_detail_id uuid,
    p_new_quantity numeric DEFAULT NULL,
    p_new_deadline timestamp DEFAULT NULL,
    p_new_delivery_date timestamp DEFAULT NULL,
    p_change_reason_id uuid DEFAULT NULL,
    p_reason varchar DEFAULT NULL,
    p_stakeholder_id uuid DEFAULT NULL,
    p_staff_id uuid DEFAULT NULL,
    p_parent_plan_change_id uuid DEFAULT NULL,
    p_remarks varchar DEFAULT NULL
) RETURNS tests.trans_plan_change AS $$
DECLARE
    v_st record; v_od tests.trans_order_detail; v_o tests.trans_order; v_old_effective timestamp; v_shipped numeric;
BEGIN
    SELECT * INTO v_st FROM tests.op_staff(p_staff_id);
    IF p_new_quantity IS NULL AND p_new_deadline IS NULL AND p_new_delivery_date IS NULL THEN
        RAISE EXCEPTION '新しい数量・完了期限・出荷納期のどれかは必須です' USING ERRCODE = 'OPR02';
    END IF;
    SELECT * INTO v_od FROM tests.trans_order_detail WHERE trans_order_detail_id = p_order_detail_id AND remove IS FALSE FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION '受注明細が見つかりません (%)', p_order_detail_id USING ERRCODE = 'OPR01';
    END IF;
    IF p_new_quantity IS NOT NULL THEN
        SELECT COALESCE(b.shipped_quantity, 0) INTO v_shipped FROM tests.v_order_detail_balance AS b
        WHERE b.trans_order_detail_id = p_order_detail_id;
        v_shipped := COALESCE(v_shipped, 0);
        IF p_new_quantity <= 0 OR p_new_quantity < v_od.cancel_quantity + v_shipped THEN
            RAISE EXCEPTION '数量は 0 より大きく、キャンセル数量(%)と出荷済み(%)の合計以上にしてください: %',
                v_od.cancel_quantity, v_shipped, p_new_quantity USING ERRCODE = 'OPR02';
        END IF;
    END IF;
    SELECT * INTO v_o FROM tests.trans_order WHERE trans_order_id = v_od.trans_order_id;
    v_old_effective := COALESCE(v_od.deadline, v_o.deadline, v_od.delivery_date, v_o.delivery_date);  -- MRP が今見ている期限
    UPDATE tests.trans_order_detail
    SET quantity = COALESCE(p_new_quantity, quantity),
        deadline = COALESCE(p_new_deadline, deadline),
        delivery_date = COALESCE(p_new_delivery_date, delivery_date),
        update_user_id = v_st.staff_id, update_user_history_id = v_st.staff_history_id
    WHERE trans_order_detail_id = p_order_detail_id;
    RETURN tests.op_add_plan_change(v_st.staff_id, v_st.staff_history_id, p_order_detail => p_order_detail_id,
        p_old_quantity => CASE WHEN p_new_quantity IS NULL THEN NULL ELSE v_od.quantity END, p_new_quantity => p_new_quantity,
        p_old_date => CASE WHEN p_new_deadline IS NOT NULL THEN v_old_effective
                           WHEN p_new_delivery_date IS NOT NULL THEN v_od.delivery_date END,
        p_new_date => COALESCE(p_new_deadline, p_new_delivery_date),
        p_change_reason_id => p_change_reason_id, p_reason => p_reason, p_stakeholder_id => p_stakeholder_id,
        p_parent => p_parent_plan_change_id, p_remarks => p_remarks);
END
$$ LANGUAGE plpgsql VOLATILE;

COMMENT ON FUNCTION tests.order_detail_change(uuid, numeric, timestamp, timestamp, uuid, varchar, uuid, uuid, uuid, varchar) IS '受注明細の納期・数量の変更。MRP が見る完了期限(deadline)を変え、計画変更(旧・新)を記録する(1トランザクション)。戻り値は計画変更';

CREATE VIEW tests.v_visiter_complaint_visiter_count AS
SELECT
    p.trans_visiter_id
    , COUNT(c.trans_visiter_id) AS all_count
    , COUNT(c.trans_visiter_id) FILTER (WHERE c.remove IS NOT TRUE) AS enable_count
    , COUNT(c.trans_visiter_id) FILTER (WHERE c.remove IS TRUE) AS disable_count
FROM
    tests.trans_visiter AS p
    LEFT JOIN tests.trans_complaint_visiter AS c
        ON c.trans_visiter_id = p.trans_visiter_id
GROUP BY
    p.trans_visiter_id;

COMMENT ON VIEW tests.v_visiter_complaint_visiter_count IS '@foreignKey (trans_visiter_id) references trans_visiter (trans_visiter_id)
@unique trans_visiter_id';

CREATE VIEW tests.v_complaint_complaint_visiter_count AS
SELECT
    p.trans_complaint_id
    , COUNT(c.trans_complaint_id) AS all_count
    , COUNT(c.trans_complaint_id) FILTER (WHERE c.remove IS NOT TRUE) AS enable_count
    , COUNT(c.trans_complaint_id) FILTER (WHERE c.remove IS TRUE) AS disable_count
FROM
    tests.trans_complaint AS p
    LEFT JOIN tests.trans_complaint_visiter AS c
        ON c.trans_complaint_id = p.trans_complaint_id
GROUP BY
    p.trans_complaint_id;

COMMENT ON VIEW tests.v_complaint_complaint_visiter_count IS '@foreignKey (trans_complaint_id) references trans_complaint (trans_complaint_id)
@unique trans_complaint_id';

CREATE VIEW tests.v_visiter_lineage AS
WITH RECURSIVE lot AS (
    SELECT v.trans_visiter_id, v.parent_trans_visiter_id
    FROM tests.trans_visiter AS v
    WHERE v.remove IS FALSE AND v.quantity > 0 AND v.adjustment IS NOT TRUE
), l (trans_visiter_id, ancestor_visiter_id, parent_id, depth, path) AS (
    SELECT lot.trans_visiter_id, lot.trans_visiter_id, lot.parent_trans_visiter_id, 0, ARRAY[lot.trans_visiter_id]
    FROM lot
    UNION ALL
    SELECT l.trans_visiter_id, p.trans_visiter_id, p.parent_trans_visiter_id, l.depth + 1, l.path || p.trans_visiter_id
    FROM l
    INNER JOIN lot AS p ON p.trans_visiter_id = l.parent_id
    WHERE NOT (p.trans_visiter_id = ANY (l.path)) AND l.depth < 50
)
SELECT
    l.trans_visiter_id
    , v.symbol
    , l.ancestor_visiter_id
    , a.symbol AS ancestor_symbol
    , l.depth
FROM l
INNER JOIN tests.trans_visiter AS v ON v.trans_visiter_id = l.trans_visiter_id
INNER JOIN tests.trans_visiter AS a ON a.trans_visiter_id = l.ancestor_visiter_id;

COMMENT ON VIEW tests.v_visiter_lineage IS '@primaryKey trans_visiter_id,ancestor_visiter_id
@foreignKey (trans_visiter_id) references trans_visiter (trans_visiter_id)
@foreignKey (ancestor_visiter_id) references trans_visiter (trans_visiter_id)
棚ビジターの分割元(自分を含む)';

CREATE VIEW tests.v_visiter_lot AS
SELECT
    v.trans_visiter_id
    , v.symbol
    , v.parent_trans_visiter_id
    , rt.root_visiter_id
    , v.trans_container_id
    , c.mstr_location_id
    , v.release
    , v.quantity AS receipt_quantity
    , COALESCE(ln.q_issue, 0) AS issue_quantity
    , COALESCE(ln.q_adj, 0) AS adjustment_quantity
    , v.quantity + COALESCE(ln.q_all, 0) AS quantity
    , COALESCE(ln.n, 0)::integer AS line_count
    , COALESCE(sp.n, 0)::integer AS split_count
    , cp.own_open_complaint_count
    , cp.open_complaint_count
FROM tests.trans_visiter AS v
LEFT JOIN tests.trans_container AS c
    ON c.trans_container_id = v.trans_container_id
LEFT JOIN LATERAL (
    -- この在庫の出庫(-)と棚卸し調整(+/-)の行
    SELECT SUM(r.quantity) AS q_all
         , -SUM(r.quantity) FILTER (WHERE r.adjustment IS NOT TRUE) AS q_issue
         , SUM(r.quantity) FILTER (WHERE r.adjustment IS TRUE) AS q_adj
         , COUNT(*) AS n
    FROM tests.trans_visiter AS r
    WHERE r.parent_trans_visiter_id = v.trans_visiter_id AND r.remove IS FALSE
      AND (r.quantity < 0 OR r.adjustment IS TRUE)
) AS ln ON TRUE
LEFT JOIN LATERAL (
    -- この在庫から分割・移動して作った在庫
    SELECT COUNT(*) AS n
    FROM tests.trans_visiter AS r
    WHERE r.parent_trans_visiter_id = v.trans_visiter_id AND r.remove IS FALSE
      AND r.quantity > 0 AND r.adjustment IS NOT TRUE
) AS sp ON TRUE
LEFT JOIN LATERAL (
    SELECT lg.ancestor_visiter_id AS root_visiter_id
    FROM tests.v_visiter_lineage AS lg
    WHERE lg.trans_visiter_id = v.trans_visiter_id
    ORDER BY lg.depth DESC
    LIMIT 1
) AS rt ON TRUE
CROSS JOIN LATERAL (
    -- 未解除の異常 (自分に付いたもの / 分割元に付いたものを含む)
    SELECT COUNT(*) FILTER (WHERE lg.depth = 0)::integer AS own_open_complaint_count
         , COUNT(*)::integer AS open_complaint_count
    FROM tests.v_visiter_lineage AS lg
    INNER JOIN tests.trans_complaint_visiter AS cv
        ON cv.trans_visiter_id = lg.ancestor_visiter_id AND cv.remove IS FALSE AND cv.release_at IS NULL
    INNER JOIN tests.trans_complaint AS cpl
        ON cpl.trans_complaint_id = cv.trans_complaint_id AND cpl.remove IS FALSE
    WHERE lg.trans_visiter_id = v.trans_visiter_id
) AS cp
WHERE v.remove IS FALSE AND v.quantity > 0 AND v.adjustment IS NOT TRUE;

COMMENT ON VIEW tests.v_visiter_lot IS '@primaryKey trans_visiter_id
@unique symbol
@foreignKey (trans_visiter_id) references trans_visiter (trans_visiter_id)
@foreignKey (parent_trans_visiter_id) references trans_visiter (trans_visiter_id)
@foreignKey (root_visiter_id) references trans_visiter (trans_visiter_id)
@foreignKey (trans_container_id) references trans_container (trans_container_id)
@foreignKey (mstr_location_id) references mstr_location (mstr_location_id)
棚在庫(ロット)';

CREATE VIEW tests.v_mrp_visiter_item AS
WITH og AS (
    -- 品目は、自分または一番近い分割元の入庫のつなぎ(受入実績・作業実績・支給・返品)で決める
    SELECT lg.trans_visiter_id, lg.depth, pd.item_id, TRUE AS finished
    FROM tests.v_visiter_lineage AS lg
    INNER JOIN tests.trans_purchase_rec_visiter AS prv
        ON prv.trans_visiter_id = lg.ancestor_visiter_id AND prv.remove IS FALSE
    INNER JOIN tests.trans_purchase_rec AS r
        ON r.trans_purchase_rec_id = prv.trans_purchase_rec_id AND r.remove IS FALSE
    INNER JOIN tests.trans_purchase_detail AS pd
        ON pd.trans_purchase_detail_id = r.trans_purchase_detail_id
    WHERE NOT EXISTS (SELECT 1 FROM tests.trans_work_plan AS w
                      WHERE w.trans_purchase_detail_id = pd.trans_purchase_detail_id AND w.remove IS FALSE)
    UNION ALL
    SELECT lg.trans_visiter_id, lg.depth, rp.item_id,
           COALESCE(wp.sequence, 1) >= (SELECT MAX(COALESCE(w2.sequence, 1)) FROM tests.trans_work_plan AS w2
                                        WHERE w2.trans_operations_plan_id = wp.trans_operations_plan_id AND w2.remove IS FALSE)
    FROM tests.v_visiter_lineage AS lg
    INNER JOIN tests.trans_work_record_visiter AS wrv
        ON wrv.trans_visiter_id = lg.ancestor_visiter_id AND wrv.remove IS FALSE
    INNER JOIN tests.trans_work_record AS wr
        ON wr.trans_work_record_id = wrv.trans_work_record_id AND wr.remove IS FALSE
    INNER JOIN tests.trans_work_plan AS wp ON wp.trans_work_plan_id = wr.trans_work_plan_id
    INNER JOIN tests.trans_operations_plan AS op ON op.trans_operations_plan_id = wp.trans_operations_plan_id
    INNER JOIN tests.trans_resource_plan AS rp ON rp.trans_resource_plan_id = op.trans_resource_plan_id
    UNION ALL
    -- 支給で入庫した在庫 (顧客支給材・発注先からの戻り)。入庫の行(分割元の無い + の行)だけ  claude/131
    SELECT lg.trans_visiter_id, lg.depth, sd.item_id, TRUE
    FROM tests.v_visiter_lineage AS lg
    INNER JOIN tests.trans_supply_visiter AS sv
        ON sv.trans_visiter_id = lg.ancestor_visiter_id AND sv.remove IS FALSE
    INNER JOIN tests.trans_visiter AS av
        ON av.trans_visiter_id = sv.trans_visiter_id AND av.quantity > 0 AND av.parent_trans_visiter_id IS NULL
    INNER JOIN tests.trans_supply_detail AS sd
        ON sd.trans_supply_detail_id = sv.trans_supply_detail_id AND sd.remove IS FALSE
    UNION ALL
    -- 返品で入庫した在庫 (顧客からの返品)。入庫の行だけ  claude/131
    SELECT lg.trans_visiter_id, lg.depth, rd.item_id, TRUE
    FROM tests.v_visiter_lineage AS lg
    INNER JOIN tests.trans_return_visiter AS rv
        ON rv.trans_visiter_id = lg.ancestor_visiter_id AND rv.remove IS FALSE
    INNER JOIN tests.trans_visiter AS av
        ON av.trans_visiter_id = rv.trans_visiter_id AND av.quantity > 0 AND av.parent_trans_visiter_id IS NULL
    INNER JOIN tests.trans_return_detail AS rd
        ON rd.trans_return_detail_id = rv.trans_return_detail_id AND rd.remove IS FALSE
), nearest AS (
    SELECT og.*, MIN(og.depth) OVER (PARTITION BY og.trans_visiter_id) AS min_depth
    FROM og
)
SELECT
    l.trans_visiter_id
    , l.symbol
    , MIN(n.item_id::text)::uuid AS item_id
    , COUNT(DISTINCT n.item_id)::integer AS item_count
    , COALESCE(BOOL_OR(n.finished), FALSE) AS finished
    , l.quantity
    , l.release
    , l.open_complaint_count
    , (l.release IS NOT TRUE OR l.open_complaint_count > 0) AS held
FROM tests.v_visiter_lot AS l
INNER JOIN tests.trans_container AS c
    ON c.trans_container_id = l.trans_container_id AND c.remove IS FALSE
LEFT JOIN nearest AS n
    ON n.trans_visiter_id = l.trans_visiter_id AND n.depth = n.min_depth
GROUP BY l.trans_visiter_id, l.symbol, l.quantity, l.release, l.open_complaint_count;

COMMENT ON VIEW tests.v_mrp_visiter_item IS '@primaryKey trans_visiter_id
@unique symbol
@foreignKey (trans_visiter_id) references trans_visiter (trans_visiter_id)
@foreignKey (item_id) references mstr_item (mstr_item_id)
棚ビジターの品目(在庫/仕掛)';

CREATE VIEW tests.v_visiter_issuable AS
SELECT
    l.trans_visiter_id
    , l.symbol
    , l.trans_container_id
    , l.quantity
    , l.release
    , l.open_complaint_count
    , (l.release IS TRUE AND l.open_complaint_count = 0 AND l.quantity > 0) AS issuable
    , (CASE
           WHEN l.release IS NOT TRUE THEN 'hold'
           WHEN l.open_complaint_count > 0 THEN 'complaint'
           WHEN l.quantity <= 0 THEN 'empty'
       END)::varchar(16) AS block_reason
FROM tests.v_visiter_lot AS l;

COMMENT ON VIEW tests.v_visiter_issuable IS '@primaryKey trans_visiter_id
@unique symbol
@foreignKey (trans_visiter_id) references trans_visiter (trans_visiter_id)
@foreignKey (trans_container_id) references trans_container (trans_container_id)
棚ビジター取り出し可否';

CREATE OR REPLACE FUNCTION tests.visiter_lock_lot(p_lot uuid)
RETURNS tests.v_visiter_issuable AS $$
DECLARE
    v_row tests.trans_visiter;
    v_iss tests.v_visiter_issuable;
BEGIN
    SELECT * INTO v_row FROM tests.trans_visiter WHERE trans_visiter_id = p_lot FOR UPDATE;
    IF NOT FOUND OR v_row.remove IS NOT FALSE OR v_row.quantity <= 0 OR v_row.adjustment IS TRUE THEN
        RAISE EXCEPTION '在庫(ロット)の棚ビジターではありません (%)', p_lot
            USING ERRCODE = 'VIS01', HINT = '出庫・棚卸しの行ではなく、+ の行(在庫)を指定してください';
    END IF;
    SELECT * INTO v_iss FROM tests.v_visiter_issuable WHERE trans_visiter_id = p_lot;
    RETURN v_iss;
END
$$ LANGUAGE plpgsql VOLATILE;

COMMENT ON FUNCTION tests.visiter_lock_lot(uuid) IS '@omit';

CREATE OR REPLACE FUNCTION tests.visiter_issue(
    p_src uuid,
    p_qty numeric,
    p_work_record_id uuid DEFAULT NULL,
    p_staff_id uuid DEFAULT NULL,
    p_location_id uuid DEFAULT NULL,
    p_at timestamp DEFAULT NULL,
    p_remarks varchar DEFAULT NULL
) RETURNS tests.trans_visiter AS $$
DECLARE
    v_st record; v_loc record; v_lot tests.v_visiter_issuable; v_out tests.trans_visiter;
BEGIN
    v_st := tests.visiter_staff(p_staff_id);
    IF p_qty IS NULL OR p_qty <= 0 THEN
        RAISE EXCEPTION '払出数量は 0 より大きくしてください (%)', p_qty USING ERRCODE = 'VIS02';
    END IF;
    v_lot := tests.visiter_lock_lot(p_src);
    IF NOT v_lot.issuable AND v_lot.block_reason IN ('hold', 'complaint') THEN
        RAISE EXCEPTION 'この在庫は取り出せません (%)', v_lot.block_reason
            USING ERRCODE = 'VIS04',
                  HINT = CASE v_lot.block_reason WHEN 'hold' THEN '仮止め(入出庫許可なし)です'
                         ELSE '未解除の異常があります(分割元を含む)。異常を解除してから払い出してください' END;
    END IF;
    IF v_lot.quantity < p_qty THEN
        RAISE EXCEPTION '在庫の数量が足りません (今の数量 %、払出 %)', v_lot.quantity, p_qty USING ERRCODE = 'VIS03';
    END IF;
    IF p_work_record_id IS NOT NULL AND NOT EXISTS (
           SELECT 1 FROM tests.trans_work_record AS w WHERE w.trans_work_record_id = p_work_record_id AND w.remove IS FALSE) THEN
        RAISE EXCEPTION '作業実績が見つかりません (%)', p_work_record_id USING ERRCODE = 'VIS07';
    END IF;
    v_loc := tests.visiter_location(v_lot.trans_container_id, p_location_id);

    INSERT INTO tests.trans_visiter (parent_trans_visiter_id, trans_container_id, quantity, remarks,
                                     update_user_id, update_user_history_id)
    VALUES (p_src, v_lot.trans_container_id, -p_qty, p_remarks, v_st.staff_id, v_st.staff_history_id)
    RETURNING * INTO v_out;
    PERFORM tests.visiter_add_convey(v_out.trans_visiter_id, v_loc.location_id, v_loc.location_history_id, v_st.staff_id, v_st.staff_history_id, p_at, p_remarks);
    IF p_work_record_id IS NOT NULL THEN
        INSERT INTO tests.trans_work_record_visiter (trans_visiter_id, trans_work_record_id, update_user_id, update_user_history_id)
        VALUES (v_out.trans_visiter_id, p_work_record_id, v_st.staff_id, v_st.staff_history_id);
    END IF;
    RETURN v_out;
END
$$ LANGUAGE plpgsql VOLATILE;

COMMENT ON FUNCTION tests.visiter_issue(uuid, numeric, uuid, uuid, uuid, timestamp, varchar) IS '棚ビジターの払出。在庫(ロット)から - の行と受払実績を作る。作業実績を渡すと製造への材料投入としてつなぐ。戻り値は - の行';

CREATE OR REPLACE FUNCTION tests.visiter_move(
    p_src uuid,
    p_container_id uuid,
    p_qty numeric,
    p_hold boolean DEFAULT false,
    p_staff_id uuid DEFAULT NULL,
    p_location_id uuid DEFAULT NULL,
    p_at timestamp DEFAULT NULL,
    p_remarks varchar DEFAULT NULL
) RETURNS tests.trans_visiter AS $$
DECLARE
    v_st record; v_src_loc record; v_dst_loc record; v_lot tests.v_visiter_issuable;
    v_out tests.trans_visiter; v_line uuid;
BEGIN
    v_st := tests.visiter_staff(p_staff_id);
    IF p_qty IS NULL OR p_qty <= 0 THEN
        RAISE EXCEPTION '移動数量は 0 より大きくしてください (%)', p_qty USING ERRCODE = 'VIS02';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM tests.trans_container AS c WHERE c.trans_container_id = p_container_id AND c.remove IS FALSE) THEN
        RAISE EXCEPTION '移動先の棚が見つかりません (%)', p_container_id USING ERRCODE = 'VIS06';
    END IF;
    v_lot := tests.visiter_lock_lot(p_src);
    IF v_lot.quantity < p_qty THEN
        RAISE EXCEPTION '在庫の数量が足りません (今の数量 %、移動 %)', v_lot.quantity, p_qty USING ERRCODE = 'VIS03';
    END IF;
    v_src_loc := tests.visiter_location(v_lot.trans_container_id, NULL);
    v_dst_loc := tests.visiter_location(p_container_id, p_location_id);

    -- 元の棚から出す (-)
    INSERT INTO tests.trans_visiter (parent_trans_visiter_id, trans_container_id, quantity, remarks,
                                     update_user_id, update_user_history_id)
    VALUES (p_src, v_lot.trans_container_id, -p_qty, p_remarks, v_st.staff_id, v_st.staff_history_id)
    RETURNING trans_visiter_id INTO v_line;
    PERFORM tests.visiter_add_convey(v_line, v_src_loc.location_id, v_src_loc.location_history_id, v_st.staff_id, v_st.staff_history_id, p_at, p_remarks);

    -- 移動先に入れる (+、親 = 元の在庫)
    INSERT INTO tests.trans_visiter (parent_trans_visiter_id, trans_container_id, quantity, release, remarks,
                                     update_user_id, update_user_history_id)
    VALUES (p_src, p_container_id, p_qty, (v_lot.release IS TRUE AND p_hold IS NOT TRUE), p_remarks,
            v_st.staff_id, v_st.staff_history_id)
    RETURNING * INTO v_out;
    PERFORM tests.visiter_add_convey(v_out.trans_visiter_id, v_dst_loc.location_id, v_dst_loc.location_history_id, v_st.staff_id, v_st.staff_history_id, p_at, p_remarks);
    RETURN v_out;
END
$$ LANGUAGE plpgsql VOLATILE;

COMMENT ON FUNCTION tests.visiter_move(uuid, uuid, numeric, boolean, uuid, uuid, timestamp, varchar) IS '棚ビジターの移動・分割・隔離。元に - の行、移動先に + の行(親 = 元の在庫)と受払実績2件を作る。p_hold で移動先を仮止め。戻り値は移動先の在庫';

CREATE OR REPLACE FUNCTION tests.visiter_adjust(
    p_lot uuid,
    p_counted numeric,
    p_staff_id uuid DEFAULT NULL,
    p_location_id uuid DEFAULT NULL,
    p_at timestamp DEFAULT NULL,
    p_remarks varchar DEFAULT '棚卸し'
) RETURNS tests.trans_visiter AS $$
DECLARE
    v_st record; v_loc record; v_lot tests.v_visiter_issuable; v_out tests.trans_visiter; v_diff numeric;
BEGIN
    v_st := tests.visiter_staff(p_staff_id);
    IF p_counted IS NULL OR p_counted < 0 THEN
        RAISE EXCEPTION '数えた数は 0 以上にしてください (%)', p_counted USING ERRCODE = 'VIS02';
    END IF;
    v_lot := tests.visiter_lock_lot(p_lot);
    v_diff := p_counted - v_lot.quantity;
    IF v_diff = 0 THEN
        RETURN NULL;
    END IF;
    v_loc := tests.visiter_location(v_lot.trans_container_id, p_location_id);

    INSERT INTO tests.trans_visiter (parent_trans_visiter_id, trans_container_id, quantity, adjustment, remarks,
                                     update_user_id, update_user_history_id)
    VALUES (p_lot, v_lot.trans_container_id, v_diff, TRUE, p_remarks, v_st.staff_id, v_st.staff_history_id)
    RETURNING * INTO v_out;
    PERFORM tests.visiter_add_convey(v_out.trans_visiter_id, v_loc.location_id, v_loc.location_history_id, v_st.staff_id, v_st.staff_history_id, p_at, p_remarks);
    RETURN v_out;
END
$$ LANGUAGE plpgsql VOLATILE;

COMMENT ON FUNCTION tests.visiter_adjust(uuid, numeric, uuid, uuid, timestamp, varchar) IS '棚卸し。数えた数に合わせる調整の行と受払実績を作る。差が無ければ何もしない(NULL)';

CREATE OR REPLACE FUNCTION tests.inventory_request_hold(
    p_inventory_request_id uuid,
    p_container_id uuid,
    p_change_reason_id uuid DEFAULT NULL,
    p_reason varchar DEFAULT NULL,
    p_staff_id uuid DEFAULT NULL,
    p_parent_plan_change_id uuid DEFAULT NULL,
    p_remarks varchar DEFAULT NULL,
    p_location_id uuid DEFAULT NULL
) RETURNS tests.trans_plan_change AS $$
DECLARE
    v_st record; v_rq tests.trans_inventory_request; v_new tests.trans_visiter;
BEGIN
    SELECT * INTO v_st FROM tests.op_staff(p_staff_id);
    SELECT * INTO v_rq FROM tests.trans_inventory_request WHERE trans_inventory_request_id = p_inventory_request_id AND remove IS FALSE FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION '引当予約が見つかりません (%)', p_inventory_request_id USING ERRCODE = 'OPR01';
    END IF;
    IF v_rq.trans_visiter_id IS NULL THEN
        RAISE EXCEPTION '引当元の在庫(trans_visiter_id)が決まっていない予約は、保管できません' USING ERRCODE = 'OPR03';
    END IF;
    IF p_container_id IS NULL OR NOT EXISTS (SELECT 1 FROM tests.trans_container WHERE trans_container_id = p_container_id AND remove IS FALSE) THEN
        RAISE EXCEPTION '保管先のコンテナが見つかりません (%)', p_container_id USING ERRCODE = 'OPR01';
    END IF;
    v_new := tests.visiter_move(v_rq.trans_visiter_id, p_container_id, v_rq.quantity, true, v_st.staff_id, p_location_id, NULL, p_remarks);
    -- 在庫を移したあとは、引当予約を移動先(仮止めの + の行)に付け替える。付け替えないと、予約が移動元のロットを指したままになる
    UPDATE tests.trans_inventory_request
    SET trans_visiter_id = v_new.trans_visiter_id, update_user_id = v_st.staff_id, update_user_history_id = v_st.staff_history_id
    WHERE trans_inventory_request_id = p_inventory_request_id;
    RETURN tests.op_add_plan_change(v_st.staff_id, v_st.staff_history_id, p_inventory_request => p_inventory_request_id,
        p_hold => true, p_container => p_container_id, p_change_reason_id => p_change_reason_id, p_reason => p_reason,
        p_parent => p_parent_plan_change_id, p_remarks => p_remarks);
END
$$ LANGUAGE plpgsql VOLATILE;

COMMENT ON FUNCTION tests.inventory_request_hold(uuid, uuid, uuid, varchar, uuid, uuid, varchar, uuid) IS '引当予約の保管。予約の在庫を選んだコンテナへ仮止めで移し(visiter_move)、予約を移動先のロットに付け替え、計画変更(hold・コンテナ)を記録する(1トランザクション)';

CREATE OR REPLACE FUNCTION tests.lot_hold(
    p_visiter_id uuid,
    p_container_id uuid,
    p_quantity numeric,
    p_change_reason_id uuid DEFAULT NULL,
    p_reason varchar DEFAULT NULL,
    p_staff_id uuid DEFAULT NULL,
    p_parent_plan_change_id uuid DEFAULT NULL,
    p_remarks varchar DEFAULT NULL,
    p_location_id uuid DEFAULT NULL
) RETURNS tests.trans_plan_change AS $$
DECLARE
    v_st record; v_new tests.trans_visiter;
BEGIN
    SELECT * INTO v_st FROM tests.op_staff(p_staff_id);
    IF p_container_id IS NULL OR NOT EXISTS (SELECT 1 FROM tests.trans_container WHERE trans_container_id = p_container_id AND remove IS FALSE) THEN
        RAISE EXCEPTION '保管先のコンテナが見つかりません (%)', p_container_id USING ERRCODE = 'OPR01';
    END IF;
    v_new := tests.visiter_move(p_visiter_id, p_container_id, p_quantity, true, v_st.staff_id, p_location_id, NULL, p_remarks);
    -- 計画変更の対象は、押さえた(仮止めした)移動先のロット。未処置一覧は、このロットが仮止めのまま残っているかで見つける
    RETURN tests.op_add_plan_change(v_st.staff_id, v_st.staff_history_id, p_visiter => v_new.trans_visiter_id,
        p_hold => true, p_container => p_container_id, p_change_reason_id => p_change_reason_id, p_reason => p_reason,
        p_parent => p_parent_plan_change_id, p_remarks => p_remarks);
END
$$ LANGUAGE plpgsql VOLATILE;

COMMENT ON FUNCTION tests.lot_hold(uuid, uuid, numeric, uuid, varchar, uuid, uuid, varchar, uuid) IS '品物を押さえる(保管)。選んだコンテナへ仮止めで移し(visiter_move)、押さえた(移動先の)ロットを対象に、計画変更(hold・コンテナ)を記録する(1トランザクション)';

CREATE OR REPLACE FUNCTION tests.lot_scrap(
    p_visiter_id uuid,
    p_quantity numeric,
    p_change_reason_id uuid DEFAULT NULL,
    p_reason varchar DEFAULT NULL,
    p_staff_id uuid DEFAULT NULL,
    p_parent_plan_change_id uuid DEFAULT NULL,
    p_remarks varchar DEFAULT NULL,
    p_location_id uuid DEFAULT NULL
) RETURNS tests.trans_plan_change AS $$
DECLARE
    v_st record;
BEGIN
    SELECT * INTO v_st FROM tests.op_staff(p_staff_id);
    PERFORM tests.visiter_issue(p_visiter_id, p_quantity, NULL, v_st.staff_id, p_location_id, NULL, p_remarks);
    RETURN tests.op_add_plan_change(v_st.staff_id, v_st.staff_history_id, p_visiter => p_visiter_id,
        p_scrap => true, p_change_reason_id => p_change_reason_id, p_reason => p_reason,
        p_parent => p_parent_plan_change_id, p_remarks => p_remarks);
END
$$ LANGUAGE plpgsql VOLATILE;

COMMENT ON FUNCTION tests.lot_scrap(uuid, numeric, uuid, varchar, uuid, uuid, varchar, uuid) IS '品物の廃棄。ロットから払い出し(visiter_issue)、計画変更(scrap)を記録する(1トランザクション)';

CREATE OR REPLACE FUNCTION tests.lot_deliver(
    p_visiter_id uuid,
    p_quantity numeric,
    p_order_detail_settlement_id uuid DEFAULT NULL,
    p_change_reason_id uuid DEFAULT NULL,
    p_reason varchar DEFAULT NULL,
    p_staff_id uuid DEFAULT NULL,
    p_parent_plan_change_id uuid DEFAULT NULL,
    p_remarks varchar DEFAULT NULL,
    p_location_id uuid DEFAULT NULL
) RETURNS tests.trans_plan_change AS $$
DECLARE
    v_st record;
BEGIN
    SELECT * INTO v_st FROM tests.op_staff(p_staff_id);
    PERFORM tests.visiter_issue(p_visiter_id, p_quantity, NULL, v_st.staff_id, p_location_id, NULL, p_remarks);
    RETURN tests.op_add_plan_change(v_st.staff_id, v_st.staff_history_id, p_visiter => p_visiter_id,
        p_deliver => true, p_settlement => p_order_detail_settlement_id,
        p_change_reason_id => p_change_reason_id, p_reason => p_reason,
        p_parent => p_parent_plan_change_id, p_remarks => p_remarks);
END
$$ LANGUAGE plpgsql VOLATILE;

COMMENT ON FUNCTION tests.lot_deliver(uuid, numeric, uuid, uuid, varchar, uuid, uuid, varchar, uuid) IS '顧客への引き渡し。ロットから払い出し(visiter_issue)、計画変更(deliver・精算)を記録する(1トランザクション)';

CREATE OR REPLACE FUNCTION tests.return_register(
    p_return_kind_id uuid,
    p_stakeholder_id uuid,
    p_details jsonb,
    p_order_id uuid DEFAULT NULL,
    p_purchase_id uuid DEFAULT NULL,
    p_plan_change_id uuid DEFAULT NULL,
    p_complaint_id uuid DEFAULT NULL,
    p_reason varchar DEFAULT NULL,
    p_code varchar DEFAULT NULL,
    p_return_at timestamp DEFAULT NULL,
    p_staff_id uuid DEFAULT NULL,
    p_remarks varchar DEFAULT NULL,
    p_location_id uuid DEFAULT NULL
) RETURNS tests.trans_return AS $$
DECLARE
    v_st record; v_kind_hist uuid; v_receive boolean; v_stake_hist uuid;
    v_ret tests.trans_return; v_det tests.trans_return_detail; d jsonb; v_issued tests.trans_visiter; v_vid text;
BEGIN
    SELECT * INTO v_st FROM tests.op_staff(p_staff_id);
    v_kind_hist := tests.op_hist_return_kind(p_return_kind_id);
    IF v_kind_hist IS NULL THEN
        RAISE EXCEPTION '返品区分が見つかりません (%)', p_return_kind_id USING ERRCODE = 'OPR00';
    END IF;
    SELECT h.receive INTO v_receive FROM tests.history_mstr_return_kind AS h WHERE h.history_id = v_kind_hist;
    v_stake_hist := tests.mrp_hist_stakeholder(p_stakeholder_id);
    IF v_stake_hist IS NULL THEN
        RAISE EXCEPTION '相手先が見つかりません (%)', p_stakeholder_id USING ERRCODE = 'OPR00';
    END IF;
    IF p_details IS NULL OR jsonb_typeof(p_details) <> 'array' OR jsonb_array_length(p_details) = 0 THEN
        RAISE EXCEPTION '明細(p_details)は1件以上の配列で渡してください' USING ERRCODE = 'OPR02';
    END IF;
    IF num_nonnulls(p_order_id, p_purchase_id) > 1 THEN
        RAISE EXCEPTION '受注と発注は、どちらか一方だけを指定してください' USING ERRCODE = 'OPR02';
    END IF;
    -- 返品区分の向き: 顧客からの返品(receive = true)は受注側、仕入先・外注先への返品(false)は発注側
    IF v_receive AND p_purchase_id IS NOT NULL THEN
        RAISE EXCEPTION '顧客からの返品(receive = true)には、発注(p_purchase_id)を指定できません' USING ERRCODE = 'OPR02';
    END IF;
    IF NOT v_receive AND p_order_id IS NOT NULL THEN
        RAISE EXCEPTION '仕入先・外注先への返品(receive = false)には、受注(p_order_id)を指定できません' USING ERRCODE = 'OPR02';
    END IF;

    INSERT INTO tests.trans_return (code, return_kind_history_id, return_kind_id, return_at, stakeholder_history_id, stakeholder_id,
        trans_order_id, trans_purchase_id, trans_plan_change_id, trans_complaint_id, reason,
        staff_history_id, staff_id, remarks, update_user_id, update_user_history_id)
    VALUES (p_code, v_kind_hist, p_return_kind_id, COALESCE(p_return_at, now()), v_stake_hist, p_stakeholder_id,
        p_order_id, p_purchase_id, p_plan_change_id, p_complaint_id, p_reason,
        v_st.staff_history_id, v_st.staff_id, p_remarks, v_st.staff_id, v_st.staff_history_id)
    RETURNING * INTO v_ret;

    FOR d IN SELECT * FROM jsonb_array_elements(p_details) LOOP
        IF (d->>'item_id') IS NULL OR COALESCE((d->>'quantity')::numeric, 0) <= 0 THEN
            RAISE EXCEPTION '明細には item_id と、0 より大きい quantity が必要です' USING ERRCODE = 'OPR02';
        END IF;
        IF v_receive AND ((d->>'purchase_detail_id') IS NOT NULL OR (d->>'purchase_rec_id') IS NOT NULL) THEN
            RAISE EXCEPTION '顧客からの返品の明細に、発注側(purchase_detail_id・purchase_rec_id)は指定できません' USING ERRCODE = 'OPR02';
        END IF;
        IF NOT v_receive AND ((d->>'order_detail_id') IS NOT NULL OR (d->>'shipping_order_detail_record_id') IS NOT NULL) THEN
            RAISE EXCEPTION '仕入先・外注先への返品の明細に、受注側(order_detail_id・shipping_order_detail_record_id)は指定できません' USING ERRCODE = 'OPR02';
        END IF;
        INSERT INTO tests.trans_return_detail (trans_return_id, item_history_id, item_id, quantity, replacement,
            trans_order_detail_id, trans_shipping_order_detail_record_id, trans_purchase_detail_id, trans_purchase_rec_id,
            origin_trans_visiter_id, update_user_id, update_user_history_id)
        VALUES (v_ret.trans_return_id, tests.mrp_hist_item((d->>'item_id')::uuid), (d->>'item_id')::uuid,
            (d->>'quantity')::numeric, COALESCE((d->>'replacement')::boolean, false),
            (d->>'order_detail_id')::uuid, (d->>'shipping_order_detail_record_id')::uuid,
            (d->>'purchase_detail_id')::uuid, (d->>'purchase_rec_id')::uuid,
            (d->>'origin_visiter_id')::uuid, v_st.staff_id, v_st.staff_history_id)
        RETURNING * INTO v_det;

        -- 仕入先・外注先への返品: ロットから払い出して、その - の行をつなぐ
        IF NOT v_receive AND (d->>'lot_id') IS NOT NULL THEN
            v_issued := tests.visiter_issue((d->>'lot_id')::uuid, (d->>'quantity')::numeric, NULL, v_st.staff_id, p_location_id, NULL, p_remarks);
            INSERT INTO tests.trans_return_visiter (trans_return_detail_id, trans_visiter_id, update_user_id, update_user_history_id)
            VALUES (v_det.trans_return_detail_id, v_issued.trans_visiter_id, v_st.staff_id, v_st.staff_history_id);
        END IF;
        -- 既存の棚ビジター(先に入庫した + の行など)をつなぐ
        IF d ? 'visiter_ids' THEN
            FOR v_vid IN SELECT jsonb_array_elements_text(d->'visiter_ids') LOOP
                INSERT INTO tests.trans_return_visiter (trans_return_detail_id, trans_visiter_id, update_user_id, update_user_history_id)
                VALUES (v_det.trans_return_detail_id, v_vid::uuid, v_st.staff_id, v_st.staff_history_id);
            END LOOP;
        END IF;
    END LOOP;
    RETURN v_ret;
END
$$ LANGUAGE plpgsql VOLATILE;

COMMENT ON FUNCTION tests.return_register(uuid, uuid, jsonb, uuid, uuid, uuid, uuid, varchar, varchar, timestamp, uuid, varchar, uuid) IS '返品の登録(伝票・明細・ロットのつなぎ)。仕入先への返品はロットから払い出す(1トランザクション)。p_details は jsonb の配列。戻り値は伝票';

CREATE OR REPLACE FUNCTION tests.supply_register(
    p_stakeholder_id uuid,
    p_receive boolean,
    p_counterpart_owns boolean,
    p_company_owns boolean,
    p_details jsonb,
    p_order_id uuid DEFAULT NULL,
    p_purchase_id uuid DEFAULT NULL,
    p_plan_change_id uuid DEFAULT NULL,
    p_complaint_id uuid DEFAULT NULL,
    p_reason varchar DEFAULT NULL,
    p_code varchar DEFAULT NULL,
    p_supply_at timestamp DEFAULT NULL,
    p_staff_id uuid DEFAULT NULL,
    p_remarks varchar DEFAULT NULL,
    p_location_id uuid DEFAULT NULL
) RETURNS tests.trans_supply AS $$
DECLARE
    v_st record; v_stake_hist uuid; v_sup tests.trans_supply; v_det tests.trans_supply_detail; d jsonb;
    v_line tests.trans_visiter; v_vid text; v_moves boolean; v_lot_qty numeric; v_lot_container uuid;
BEGIN
    SELECT * INTO v_st FROM tests.op_staff(p_staff_id);
    -- 在庫を動かすのは、渡す・返す場面だけ(receive = false で、返却不要の譲渡でも、無償 → 有償の切り替えでもない)。
    -- 譲渡(company_owns)・切り替え(trans_complaint_id あり)は、すでにあるロットの所有者を変えるだけで、在庫は動かさない。
    v_moves := NOT p_receive AND NOT p_company_owns AND p_complaint_id IS NULL;
    v_stake_hist := tests.mrp_hist_stakeholder(p_stakeholder_id);
    IF v_stake_hist IS NULL THEN
        RAISE EXCEPTION '相手先が見つかりません (%)', p_stakeholder_id USING ERRCODE = 'OPR00';
    END IF;
    IF p_receive IS NULL OR p_counterpart_owns IS NULL OR p_company_owns IS NULL THEN
        RAISE EXCEPTION 'receive・counterpart_owns・company_owns は必須です' USING ERRCODE = 'OPR02';
    END IF;
    IF p_counterpart_owns AND p_company_owns THEN
        RAISE EXCEPTION 'counterpart_owns と company_owns は、両方 true にできません' USING ERRCODE = 'OPR02';
    END IF;
    IF num_nonnulls(p_order_id, p_purchase_id) > 1 THEN
        RAISE EXCEPTION '受注と発注は、どちらか一方だけを指定してください' USING ERRCODE = 'OPR02';
    END IF;
    IF p_details IS NULL OR jsonb_typeof(p_details) <> 'array' OR jsonb_array_length(p_details) = 0 THEN
        RAISE EXCEPTION '明細(p_details)は1件以上の配列で渡してください' USING ERRCODE = 'OPR02';
    END IF;

    INSERT INTO tests.trans_supply (code, supply_at, stakeholder_history_id, stakeholder_id, receive, counterpart_owns, company_owns,
        trans_order_id, trans_purchase_id, trans_plan_change_id, trans_complaint_id, reason,
        staff_history_id, staff_id, remarks, update_user_id, update_user_history_id)
    VALUES (p_code, COALESCE(p_supply_at, now()), v_stake_hist, p_stakeholder_id, p_receive, p_counterpart_owns, p_company_owns,
        p_order_id, p_purchase_id, p_plan_change_id, p_complaint_id, p_reason,
        v_st.staff_history_id, v_st.staff_id, p_remarks, v_st.staff_id, v_st.staff_history_id)
    RETURNING * INTO v_sup;

    FOR d IN SELECT * FROM jsonb_array_elements(p_details) LOOP
        IF (d->>'item_id') IS NULL OR COALESCE((d->>'quantity')::numeric, 0) <= 0 THEN
            RAISE EXCEPTION '明細には item_id と、0 より大きい quantity が必要です' USING ERRCODE = 'OPR02';
        END IF;
        INSERT INTO tests.trans_supply_detail (trans_supply_id, item_history_id, item_id, quantity, unit_price, scheduled_at,
            trans_order_detail_id, trans_purchase_detail_id, trans_resource_plan_id, update_user_id, update_user_history_id)
        VALUES (v_sup.trans_supply_id, tests.mrp_hist_item((d->>'item_id')::uuid), (d->>'item_id')::uuid,
            (d->>'quantity')::numeric, (d->>'unit_price')::numeric, (d->>'scheduled_at')::timestamp,
            (d->>'order_detail_id')::uuid, (d->>'purchase_detail_id')::uuid, (d->>'resource_plan_id')::uuid,
            v_st.staff_id, v_st.staff_history_id)
        RETURNING * INTO v_det;

        IF NOT v_moves AND (d->>'lot_id') IS NOT NULL THEN
            -- 動かさない場面(譲渡・切り替え): 所有者はロット単位で変わる(トリガーが決める)。
            -- ロットの数量が支給の数量より多いときは、ロット全体が相手の物・自社の物になってしまうため、
            -- 先に同じ棚の中でロットを分け(visiter_move。- の行と + の行)、分けた数量のロットをつなぐ。
            SELECT l.quantity, l.trans_container_id INTO v_lot_qty, v_lot_container
            FROM tests.v_visiter_lot AS l WHERE l.trans_visiter_id = (d->>'lot_id')::uuid;
            IF NOT FOUND THEN
                RAISE EXCEPTION '棚ビジター(ロット)が見つかりません (%)', d->>'lot_id' USING ERRCODE = 'OPR01';
            END IF;
            IF v_lot_qty < (d->>'quantity')::numeric THEN
                RAISE EXCEPTION 'ロットの数量(%)が、支給の数量(%)に足りません', v_lot_qty, d->>'quantity' USING ERRCODE = 'OPR02';
            END IF;
            IF v_lot_qty > (d->>'quantity')::numeric THEN
                v_line := tests.visiter_move((d->>'lot_id')::uuid, v_lot_container, (d->>'quantity')::numeric, false,
                    v_st.staff_id, p_location_id, NULL, p_remarks);
            ELSE
                SELECT * INTO v_line FROM tests.trans_visiter WHERE trans_visiter_id = (d->>'lot_id')::uuid;
            END IF;
            INSERT INTO tests.trans_supply_visiter (trans_supply_detail_id, trans_visiter_id, update_user_id, update_user_history_id)
            VALUES (v_det.trans_supply_detail_id, v_line.trans_visiter_id, v_st.staff_id, v_st.staff_history_id);
        ELSIF v_moves AND (d->>'lot_id') IS NOT NULL THEN
            IF (d->>'container_id') IS NOT NULL THEN
                -- 選んだコンテナへ移した + の行(発注先へ渡す・発注先へ有償で渡す・無償 → 有償の切り替えなど)
                v_line := tests.visiter_move((d->>'lot_id')::uuid, (d->>'container_id')::uuid, (d->>'quantity')::numeric,
                    COALESCE((d->>'hold')::boolean, false), v_st.staff_id, p_location_id, NULL, p_remarks);
            ELSE
                -- ロットから払い出した - の行(顧客へ返す)
                v_line := tests.visiter_issue((d->>'lot_id')::uuid, (d->>'quantity')::numeric, NULL, v_st.staff_id, p_location_id, NULL, p_remarks);
            END IF;
            INSERT INTO tests.trans_supply_visiter (trans_supply_detail_id, trans_visiter_id, update_user_id, update_user_history_id)
            VALUES (v_det.trans_supply_detail_id, v_line.trans_visiter_id, v_st.staff_id, v_st.staff_history_id);
        END IF;
        IF d ? 'visiter_ids' THEN
            FOR v_vid IN SELECT jsonb_array_elements_text(d->'visiter_ids') LOOP
                INSERT INTO tests.trans_supply_visiter (trans_supply_detail_id, trans_visiter_id, update_user_id, update_user_history_id)
                VALUES (v_det.trans_supply_detail_id, v_vid::uuid, v_st.staff_id, v_st.staff_history_id);
            END LOOP;
        END IF;
    END LOOP;
    RETURN v_sup;
END
$$ LANGUAGE plpgsql VOLATILE;

COMMENT ON FUNCTION tests.supply_register(uuid, boolean, boolean, boolean, jsonb, uuid, uuid, uuid, uuid, varchar, varchar, timestamp, uuid, varchar, uuid) IS '支給の登録(伝票・明細・ロットのつなぎ)。渡すときはロットを移す・払い出す(1トランザクション)。所有者はトリガーが決める。p_details は jsonb の配列。戻り値は伝票';

CREATE VIEW tests.v_item_on_hand AS
SELECT
    vi.item_id
    , i.symbol AS item_symbol
    , i.code AS item_code
    , SUM(vi.quantity) AS on_hand_quantity
    , COALESCE(SUM(vi.quantity) FILTER (WHERE vi.held), 0) AS held_quantity
    , COALESCE(SUM(vi.quantity) FILTER (WHERE NOT vi.held AND ow.trans_visiter_id IS NULL), 0) AS available_quantity
    , COUNT(*) FILTER (WHERE vi.quantity > 0)::integer AS visiter_count
    , COUNT(*) FILTER (WHERE vi.held AND vi.quantity > 0)::integer AS held_visiter_count
    -- 社外(顧客・発注先)の所有物。現在庫には含むが、使える在庫(available_quantity)には数えない  claude/131
    , COALESCE(SUM(vi.quantity) FILTER (WHERE ow.trans_visiter_id IS NOT NULL), 0) AS external_quantity
    , COUNT(*) FILTER (WHERE ow.trans_visiter_id IS NOT NULL AND vi.quantity > 0)::integer AS external_visiter_count
FROM tests.v_mrp_visiter_item AS vi
INNER JOIN tests.mstr_item AS i ON i.mstr_item_id = vi.item_id
LEFT JOIN tests.trans_visiter_owner AS ow
    ON ow.trans_visiter_id = vi.trans_visiter_id AND ow.remove IS FALSE AND ow.owner_stakeholder_id IS NOT NULL
WHERE vi.finished AND vi.item_count = 1 AND vi.item_id IS NOT NULL
GROUP BY vi.item_id, i.symbol, i.code;

COMMENT ON VIEW tests.v_item_on_hand IS '@primaryKey item_id
@unique item_symbol
@foreignKey (item_id) references mstr_item (mstr_item_id)
品目別現在庫';

CREATE VIEW tests.v_visiter_hold_without_complaint AS
SELECT
    l.trans_visiter_id
    , l.symbol
    , l.trans_container_id
    , l.mstr_location_id
    , l.quantity
    , v.update_at AS hold_at
    , v.update_user_id
FROM tests.v_visiter_lot AS l
INNER JOIN tests.trans_visiter AS v
    ON v.trans_visiter_id = l.trans_visiter_id
WHERE l.release IS NOT TRUE
  AND NOT EXISTS (
      SELECT 1
      FROM tests.v_visiter_lineage AS lg
      INNER JOIN tests.trans_complaint_visiter AS cv
          ON cv.trans_visiter_id = lg.ancestor_visiter_id AND cv.remove IS FALSE
      INNER JOIN tests.trans_complaint AS cp
          ON cp.trans_complaint_id = cv.trans_complaint_id AND cp.remove IS FALSE
      WHERE lg.trans_visiter_id = l.trans_visiter_id
  );

COMMENT ON VIEW tests.v_visiter_hold_without_complaint IS '@primaryKey trans_visiter_id
@unique symbol
@foreignKey (trans_visiter_id) references trans_visiter (trans_visiter_id)
@foreignKey (trans_container_id) references trans_container (trans_container_id)
@foreignKey (mstr_location_id) references mstr_location (mstr_location_id)
異常の登録が無い仮止め';

CREATE VIEW tests.v_visiter_ledger_issue AS
-- negative_balance  : 在庫の今の数量がマイナス(出しすぎ)
-- orphan_line       : 出庫・棚卸しの行の親が無い、または親が在庫の行ではない
-- invalid_parent    : 分割・移動で作った在庫の親が在庫の行ではない
-- container_mismatch: 出庫・棚卸しの行の棚が、親の在庫の棚と違う
-- zero_line         : 数量0の行
SELECT
    l.trans_visiter_id
    , l.symbol
    , 'negative_balance'::varchar(32) AS issue_kind
    , l.receipt_quantity AS row_quantity
    , l.quantity AS balance
    , l.parent_trans_visiter_id
    , l.trans_container_id
FROM tests.v_visiter_lot AS l
WHERE l.quantity < 0
UNION ALL
SELECT
    r.trans_visiter_id
    , r.symbol
    , (CASE
           WHEN r.quantity = 0 THEN 'zero_line'
           WHEN r.quantity > 0 AND r.adjustment IS NOT TRUE THEN 'invalid_parent'
           WHEN p.trans_visiter_id IS NULL OR p.quantity <= 0 OR p.adjustment IS TRUE THEN 'orphan_line'
           ELSE 'container_mismatch'
       END)::varchar(32)
    , r.quantity
    , NULL::decimal(10,2)
    , r.parent_trans_visiter_id
    , r.trans_container_id
FROM tests.trans_visiter AS r
LEFT JOIN tests.trans_visiter AS p
    ON p.trans_visiter_id = r.parent_trans_visiter_id AND p.remove IS FALSE
WHERE r.remove IS FALSE
  AND (
        r.quantity = 0
     OR ((r.quantity < 0 OR r.adjustment IS TRUE)
         AND (p.trans_visiter_id IS NULL OR p.quantity <= 0 OR p.adjustment IS TRUE
              OR p.trans_container_id IS DISTINCT FROM r.trans_container_id))
     OR (r.quantity > 0 AND r.adjustment IS NOT TRUE AND r.parent_trans_visiter_id IS NOT NULL
         AND (p.trans_visiter_id IS NULL OR p.quantity <= 0 OR p.adjustment IS TRUE))
  );

COMMENT ON VIEW tests.v_visiter_ledger_issue IS '@primaryKey trans_visiter_id,issue_kind
@foreignKey (trans_visiter_id) references trans_visiter (trans_visiter_id)
@foreignKey (parent_trans_visiter_id) references trans_visiter (trans_visiter_id)
@foreignKey (trans_container_id) references trans_container (trans_container_id)
棚ビジターの行の不備';

CREATE VIEW tests.v_visiter_origin_check AS
SELECT
    x.origin_kind
    , x.origin_id
    , x.origin_symbol
    , x.trans_purchase_rec_id
    , x.trans_work_record_id
    , x.record_quantity
    , x.visiter_quantity
    , x.record_quantity - x.visiter_quantity AS difference
    , x.visiter_count
FROM (
    SELECT
        'purchase_rec'::varchar(16) AS origin_kind
        , r.trans_purchase_rec_id AS origin_id
        , r.symbol AS origin_symbol
        , r.trans_purchase_rec_id
        , NULL::uuid AS trans_work_record_id
        , COALESCE(r.quantity, 0) AS record_quantity
        , COALESCE(lt.q, 0) AS visiter_quantity
        , COALESCE(lt.n, 0)::integer AS visiter_count
    FROM tests.trans_purchase_rec AS r
    LEFT JOIN LATERAL (
        SELECT SUM(v.quantity) AS q, COUNT(*) AS n
        FROM tests.trans_purchase_rec_visiter AS prv
        INNER JOIN tests.trans_visiter AS v
            ON v.trans_visiter_id = prv.trans_visiter_id AND v.remove IS FALSE
           AND v.quantity > 0 AND v.adjustment IS NOT TRUE
        WHERE prv.trans_purchase_rec_id = r.trans_purchase_rec_id AND prv.remove IS FALSE
    ) AS lt ON TRUE
    WHERE r.remove IS FALSE
    UNION ALL
    SELECT
        'work_record'
        , w.trans_work_record_id
        , w.symbol
        , NULL::uuid
        , w.trans_work_record_id
        , COALESCE(w.qty, 0)
        , COALESCE(lt.q, 0)
        , COALESCE(lt.n, 0)::integer
    FROM tests.trans_work_record AS w
    LEFT JOIN LATERAL (
        SELECT SUM(v.quantity) AS q, COUNT(*) AS n
        FROM tests.trans_work_record_visiter AS wrv
        INNER JOIN tests.trans_visiter AS v
            ON v.trans_visiter_id = wrv.trans_visiter_id AND v.remove IS FALSE
           AND v.quantity > 0 AND v.adjustment IS NOT TRUE
        WHERE wrv.trans_work_record_id = w.trans_work_record_id AND wrv.remove IS FALSE
    ) AS lt ON TRUE
    WHERE w.remove IS FALSE
) AS x
WHERE x.record_quantity <> x.visiter_quantity;

COMMENT ON VIEW tests.v_visiter_origin_check IS '@primaryKey origin_kind,origin_id
@foreignKey (trans_purchase_rec_id) references trans_purchase_rec (trans_purchase_rec_id)
@foreignKey (trans_work_record_id) references trans_work_record (trans_work_record_id)
入庫数量不一致(受入実績・作業実績)';

CREATE VIEW tests.v_complaint_target_visiter AS
WITH tgt AS (
    SELECT t.trans_complaint_id, 'purchase_rec'::varchar(16) AS target_kind, t.trans_complaint_purchase_rec_id AS target_link_id,
           t.trans_purchase_rec_id, NULL::uuid AS trans_work_record_id, NULL::uuid AS target_visiter_id, t.quantity AS complaint_quantity,
           NULL::uuid AS trans_supply_detail_id
    FROM tests.trans_complaint_purchase_rec AS t
    WHERE t.remove IS FALSE
    UNION ALL
    SELECT t.trans_complaint_id, 'work_record', t.trans_complaint_work_id,
           NULL::uuid, t.trans_work_record_id, NULL::uuid, t.quantity, NULL::uuid
    FROM tests.trans_complaint_work AS t
    WHERE t.remove IS FALSE
    UNION ALL
    SELECT t.trans_complaint_id, 'visiter', t.trans_complaint_visiter_id,
           NULL::uuid, NULL::uuid, t.trans_visiter_id, t.quantity, NULL::uuid
    FROM tests.trans_complaint_visiter AS t
    WHERE t.remove IS FALSE
    UNION ALL
    -- 支給品の検品で見つかった異常  claude/131
    SELECT t.trans_complaint_id, 'supply', t.trans_complaint_supply_id,
           NULL::uuid, NULL::uuid, NULL::uuid, t.quantity, t.trans_supply_detail_id
    FROM tests.trans_complaint_supply AS t
    WHERE t.remove IS FALSE
), src AS (
    -- 異常の対象から直接作られた在庫
    SELECT tg.target_link_id, prv.trans_visiter_id
    FROM tgt AS tg
    INNER JOIN tests.trans_purchase_rec_visiter AS prv
        ON prv.trans_purchase_rec_id = tg.trans_purchase_rec_id AND prv.remove IS FALSE
    WHERE tg.target_kind = 'purchase_rec'
    UNION
    SELECT tg.target_link_id, wrv.trans_visiter_id
    FROM tgt AS tg
    INNER JOIN tests.trans_work_record_visiter AS wrv
        ON wrv.trans_work_record_id = tg.trans_work_record_id AND wrv.remove IS FALSE
    INNER JOIN tests.trans_visiter AS v
        ON v.trans_visiter_id = wrv.trans_visiter_id AND v.quantity > 0
    WHERE tg.target_kind = 'work_record'
    UNION
    SELECT tg.target_link_id, tg.target_visiter_id
    FROM tgt AS tg
    WHERE tg.target_kind = 'visiter'
    UNION
    SELECT tg.target_link_id, sv.trans_visiter_id
    FROM tgt AS tg
    INNER JOIN tests.trans_supply_visiter AS sv
        ON sv.trans_supply_detail_id = tg.trans_supply_detail_id AND sv.remove IS FALSE
    INNER JOIN tests.trans_visiter AS v
        ON v.trans_visiter_id = sv.trans_visiter_id AND v.quantity > 0
    WHERE tg.target_kind = 'supply'
), dv AS (
    -- その在庫と、そこから分割・移動して作った在庫
    SELECT DISTINCT s.target_link_id, lg.trans_visiter_id
    FROM src AS s
    INNER JOIN tests.v_visiter_lineage AS lg ON lg.ancestor_visiter_id = s.trans_visiter_id
)
SELECT
    md5(concat_ws('|', tg.target_kind, tg.target_link_id, iss.trans_visiter_id)) AS complaint_target_visiter_key
    , tg.trans_complaint_id
    , cp.symbol AS complaint_symbol
    , tg.target_kind
    , tg.target_link_id
    , tg.trans_purchase_rec_id
    , tg.trans_work_record_id
    , tg.trans_supply_detail_id
    , tg.complaint_quantity
    , iss.trans_visiter_id
    , iss.symbol AS visiter_symbol
    , iss.quantity AS visiter_quantity
    , iss.release
    , lk.trans_complaint_visiter_id
    , (lk.trans_complaint_visiter_id IS NOT NULL) AS linked
    , lk.release_at
    , (CASE
           WHEN iss.trans_visiter_id IS NULL THEN NULL
           WHEN iss.quantity <= 0 THEN 'empty'
           WHEN NOT iss.issuable THEN 'held'
           ELSE 'issuable'
       END)::varchar(16) AS visiter_status
FROM tgt AS tg
INNER JOIN tests.trans_complaint AS cp
    ON cp.trans_complaint_id = tg.trans_complaint_id AND cp.remove IS FALSE
LEFT JOIN dv ON dv.target_link_id = tg.target_link_id
LEFT JOIN tests.v_visiter_issuable AS iss
    ON iss.trans_visiter_id = dv.trans_visiter_id
LEFT JOIN LATERAL (
    -- 同じ異常が、自分か分割元に付いているか
    SELECT cv.trans_complaint_visiter_id, cv.release_at
    FROM tests.v_visiter_lineage AS lg
    INNER JOIN tests.trans_complaint_visiter AS cv
        ON cv.trans_visiter_id = lg.ancestor_visiter_id
       AND cv.trans_complaint_id = tg.trans_complaint_id AND cv.remove IS FALSE
    WHERE lg.trans_visiter_id = iss.trans_visiter_id
    ORDER BY cv.release_at NULLS FIRST, lg.depth
    LIMIT 1
) AS lk ON TRUE
WHERE dv.trans_visiter_id IS NULL OR iss.trans_visiter_id IS NOT NULL;

COMMENT ON VIEW tests.v_complaint_target_visiter IS '@primaryKey complaint_target_visiter_key
@foreignKey (trans_complaint_id) references trans_complaint (trans_complaint_id)
@foreignKey (trans_purchase_rec_id) references trans_purchase_rec (trans_purchase_rec_id)
@foreignKey (trans_supply_detail_id) references trans_supply_detail (trans_supply_detail_id)
@foreignKey (trans_work_record_id) references trans_work_record (trans_work_record_id)
@foreignKey (trans_visiter_id) references trans_visiter (trans_visiter_id)
@foreignKey (trans_complaint_visiter_id) references trans_complaint_visiter (trans_complaint_visiter_id)
異常の対象と棚ビジター';

CREATE VIEW tests.v_complaint_target AS
SELECT
    t.target_link_id
    , t.trans_complaint_id
    , t.complaint_symbol
    , t.target_kind
    , t.trans_purchase_rec_id
    , t.trans_work_record_id
    , t.trans_supply_detail_id
    , t.complaint_quantity
    , COUNT(t.trans_visiter_id)::integer AS visiter_count
    , COALESCE(SUM(t.visiter_quantity), 0) AS visiter_quantity
    , COUNT(*) FILTER (WHERE t.linked)::integer AS linked_count
    , COUNT(*) FILTER (WHERE t.linked AND t.release_at IS NULL)::integer AS open_count
    , COUNT(*) FILTER (WHERE t.trans_visiter_id IS NOT NULL AND NOT t.linked)::integer AS missing_count
    , COUNT(*) FILTER (WHERE t.trans_visiter_id IS NOT NULL AND NOT t.linked AND t.visiter_status = 'issuable')::integer AS missing_issuable_count
    , COUNT(*) FILTER (WHERE t.trans_visiter_id IS NOT NULL AND NOT t.linked AND t.visiter_status = 'empty')::integer AS missing_empty_count
FROM tests.v_complaint_target_visiter AS t
GROUP BY t.target_link_id, t.trans_complaint_id, t.complaint_symbol, t.target_kind, t.trans_purchase_rec_id, t.trans_work_record_id, t.trans_supply_detail_id, t.complaint_quantity;

COMMENT ON VIEW tests.v_complaint_target IS '@primaryKey target_link_id
@foreignKey (trans_complaint_id) references trans_complaint (trans_complaint_id)
@foreignKey (trans_purchase_rec_id) references trans_purchase_rec (trans_purchase_rec_id)
@foreignKey (trans_supply_detail_id) references trans_supply_detail (trans_supply_detail_id)
@foreignKey (trans_work_record_id) references trans_work_record (trans_work_record_id)
異常の対象';

CREATE VIEW tests.v_shelf_inventory_status AS
-- 6. 棚在庫状況 (2026-11-01 改訂: 数量は棚ビジターだけ。1行 = 在庫(ロット) 1件)
-- フィルタ: 受入実績(trans_purchase_rec_ids ※配列・分割元を含む), 作業実績(trans_work_record_ids ※配列・分割元を含む),
--           投入先の作業実績(consumed_work_record_ids ※配列), 受払実績(trans_convey_ids ※配列),
--           入出庫許可(release), 今の数量(quantity), コンテナID(trans_container_id), 場所ID(mstr_location_id)
SELECT
    l.trans_visiter_id
    , l.symbol
    , l.parent_trans_visiter_id
    , l.root_visiter_id
    , l.trans_container_id
    , l.mstr_location_id
    , l.release
    , l.quantity
    , l.receipt_quantity
    , l.issue_quantity
    , l.adjustment_quantity
    , l.line_count
    , l.split_count
    , l.open_complaint_count
    , COALESCE(pr.ids, ARRAY[]::uuid[]) AS trans_purchase_rec_ids
    , COALESCE(pr.n, 0)::integer AS purchase_rec_count
    , COALESCE(wr.ids, ARRAY[]::uuid[]) AS trans_work_record_ids
    , COALESCE(wr.n, 0)::integer AS work_record_count
    , COALESCE(us.ids, ARRAY[]::uuid[]) AS consumed_work_record_ids
    , COALESCE(us.n, 0)::integer AS consumed_work_record_count
    , COALESCE(cv.ids, ARRAY[]::uuid[]) AS trans_convey_ids
    , COALESCE(cv.n, 0)::integer AS convey_count
    , cv.last_at AS last_convey_at
FROM tests.v_visiter_lot AS l
INNER JOIN tests.trans_container AS c
    ON c.trans_container_id = l.trans_container_id AND c.remove IS FALSE
LEFT JOIN LATERAL (
    SELECT ARRAY_AGG(DISTINCT prv.trans_purchase_rec_id) AS ids, COUNT(DISTINCT prv.trans_purchase_rec_id) AS n
    FROM tests.v_visiter_lineage AS lg
    INNER JOIN tests.trans_purchase_rec_visiter AS prv
        ON prv.trans_visiter_id = lg.ancestor_visiter_id AND prv.remove IS FALSE
    INNER JOIN tests.trans_purchase_rec AS r
        ON r.trans_purchase_rec_id = prv.trans_purchase_rec_id AND r.remove IS FALSE
    WHERE lg.trans_visiter_id = l.trans_visiter_id
) AS pr ON TRUE
LEFT JOIN LATERAL (
    SELECT ARRAY_AGG(DISTINCT wrv.trans_work_record_id) AS ids, COUNT(DISTINCT wrv.trans_work_record_id) AS n
    FROM tests.v_visiter_lineage AS lg
    INNER JOIN tests.trans_work_record_visiter AS wrv
        ON wrv.trans_visiter_id = lg.ancestor_visiter_id AND wrv.remove IS FALSE
    INNER JOIN tests.trans_work_record AS w
        ON w.trans_work_record_id = wrv.trans_work_record_id AND w.remove IS FALSE
    WHERE lg.trans_visiter_id = l.trans_visiter_id
) AS wr ON TRUE
LEFT JOIN LATERAL (
    -- この在庫から材料として投入した作業実績 (出庫の行につながる作業実績)
    SELECT ARRAY_AGG(DISTINCT wrv.trans_work_record_id) AS ids, COUNT(DISTINCT wrv.trans_work_record_id) AS n
    FROM tests.trans_visiter AS r
    INNER JOIN tests.trans_work_record_visiter AS wrv
        ON wrv.trans_visiter_id = r.trans_visiter_id AND wrv.remove IS FALSE
    INNER JOIN tests.trans_work_record AS w
        ON w.trans_work_record_id = wrv.trans_work_record_id AND w.remove IS FALSE
    WHERE r.parent_trans_visiter_id = l.trans_visiter_id AND r.remove IS FALSE AND r.quantity < 0
) AS us ON TRUE
LEFT JOIN LATERAL (
    -- この在庫の行と、その出庫・棚卸しの行の受払実績
    SELECT ARRAY_AGG(cn.trans_convey_id ORDER BY cn.convey_at, cn.trans_convey_id) AS ids, COUNT(*) AS n, MAX(cn.convey_at) AS last_at
    FROM tests.trans_convey AS cn
    INNER JOIN tests.trans_visiter AS r
        ON r.trans_visiter_id = cn.trans_visiter_id AND r.remove IS FALSE
    WHERE cn.remove IS FALSE
      AND (r.trans_visiter_id = l.trans_visiter_id
           OR (r.parent_trans_visiter_id = l.trans_visiter_id AND (r.quantity < 0 OR r.adjustment IS TRUE)))
) AS cv ON TRUE;

COMMENT ON VIEW tests.v_shelf_inventory_status IS '@primaryKey trans_visiter_id
@unique symbol
@foreignKey (trans_visiter_id) references trans_visiter (trans_visiter_id)
@foreignKey (parent_trans_visiter_id) references trans_visiter (trans_visiter_id)
@foreignKey (trans_container_id) references trans_container (trans_container_id)
@foreignKey (mstr_location_id) references mstr_location (mstr_location_id)
棚在庫状況';

CREATE VIEW tests.v_work_plan_delivery_compliance AS
SELECT
    x.trans_work_plan_id
    , x.trans_operations_plan_id
    , x.mstr_task_id
    , x.start_at
    , x.completion_at
    , x.deadline
    , x.trans_work_record_ids
    , x.work_record_count
    , x.planned_quantity
    , x.work_quantity
    , x.is_completed
    , x.first_start_at
    , CASE WHEN x.is_completed THEN x.last_stop_at END AS completed_at
    , CASE
        WHEN x.is_completed AND x.completion_at IS NULL THEN 'NO_DEADLINE'
        WHEN x.is_completed AND x.last_stop_at <= x.completion_at THEN 'ON_TIME'
        WHEN x.is_completed THEN 'LATE'
        WHEN x.completion_at < CURRENT_TIMESTAMP THEN 'OVERDUE'
        ELSE 'PENDING'
      END AS compliance_status
FROM
    (
        SELECT
            wp.trans_work_plan_id
            , wp.trans_operations_plan_id
            , wp.mstr_task_id
            , wp.start_at
            , wp.completion_at
            , op.deadline
            , COALESCE(wr.trans_work_record_ids, ARRAY[]::UUID[]) AS trans_work_record_ids
            , COALESCE(wr.work_record_count, 0) AS work_record_count
            , rp.quantity AS planned_quantity
            , COALESCE(wr.work_quantity, 0) AS work_quantity
            , CASE
                WHEN rp.quantity IS NOT NULL THEN COALESCE(wr.work_quantity, 0) >= rp.quantity
                ELSE COALESCE(wr.work_record_count, 0) > 0
              END AS is_completed
            , wr.first_start_at
            , wr.last_stop_at
        FROM
            tests.trans_work_plan AS wp
            INNER JOIN tests.trans_operations_plan AS op
                ON op.trans_operations_plan_id = wp.trans_operations_plan_id
                AND op.remove IS FALSE
            INNER JOIN tests.mstr_task AS t
                ON t.mstr_task_id = wp.mstr_task_id
                AND t.remove IS FALSE
            LEFT JOIN tests.trans_resource_plan AS rp
                ON rp.trans_resource_plan_id = op.trans_resource_plan_id
                AND rp.remove IS FALSE
            LEFT JOIN LATERAL (
                SELECT
                    ARRAY_AGG(w.trans_work_record_id ORDER BY w.nth_time, w.start_at) AS trans_work_record_ids
                    , COUNT(w.trans_work_record_id) AS work_record_count
                    , SUM(w.qty) AS work_quantity
                    , MIN(w.start_at) AS first_start_at
                    , MAX(w.stop_at) AS last_stop_at
                FROM
                    tests.trans_work_record AS w
                WHERE
                    w.trans_work_plan_id = wp.trans_work_plan_id
                    AND w.remove IS FALSE
            ) AS wr
                ON TRUE
        WHERE
            wp.remove IS FALSE
    ) AS x;

COMMENT ON VIEW tests.v_work_plan_delivery_compliance IS '@primaryKey trans_work_plan_id
@foreignKey (trans_work_plan_id) references trans_work_plan (trans_work_plan_id)
@foreignKey (trans_operations_plan_id) references trans_operations_plan (trans_operations_plan_id)
@foreignKey (mstr_task_id) references mstr_task (mstr_task_id)
生産計画納期遵守状況';

CREATE VIEW tests.v_inspection_status AS
SELECT
    e.mstr_equipment_id
    , st.mstr_stakeholder_id AS supplier_id
    , (rc.trans_inspect_record_id IS NOT NULL) AS is_implemented
    , rc.result
    , COUNT(sd.trans_inspect_sch_detail_id) AS schedule_detail_count
    , COUNT(sd.trans_inspect_sch_detail_id) FILTER (WHERE rc.trans_inspect_record_id IS NULL AND sd.scheduled_end_date < CURRENT_TIMESTAMP) AS overdue_count
    , MIN(sd.scheduled_start_date) FILTER (WHERE rc.trans_inspect_record_id IS NULL) AS next_scheduled_start_date
    , MAX(rc.implement_stop_date) AS last_implement_date
FROM
    tests.trans_inspect_sch_detail AS sd
    INNER JOIN tests.trans_inspect_sch AS s
        ON s.trans_inspect_sch_id = sd.trans_inspect_sch_id
        AND s.remove IS FALSE
    INNER JOIN tests.mstr_equipment AS e
        ON e.mstr_equipment_id = s.equipment_id
        AND e.remove IS FALSE
    LEFT JOIN tests.mstr_stakeholder AS st
        ON st.mstr_stakeholder_id = sd.stakeholder_id
        AND st.remove IS FALSE
    LEFT JOIN LATERAL (
        SELECT
            r.trans_inspect_record_id
            , r.result
            , r.implement_stop_date
        FROM
            tests.trans_inspect_record AS r
        WHERE
            r.trans_inspect_sch_detail_id = sd.trans_inspect_sch_detail_id
            AND r.remove IS FALSE
        ORDER BY
            r.implement_stop_date DESC NULLS LAST
            , r.update_at DESC
        LIMIT 1
    ) AS rc
        ON TRUE
WHERE
    sd.remove IS FALSE
GROUP BY
    e.mstr_equipment_id
    , st.mstr_stakeholder_id
    , (rc.trans_inspect_record_id IS NOT NULL)
    , rc.result;

COMMENT ON VIEW tests.v_inspection_status IS '@foreignKey (mstr_equipment_id) references mstr_equipment (mstr_equipment_id)
@foreignKey (supplier_id) references mstr_stakeholder (mstr_stakeholder_id)
点検整備実施状況';

CREATE VIEW tests.v_shipping_delivery_compliance AS
SELECT
    x.customer_id
    , x.mstr_item_kind_id
    , x.mstr_item_id
    , x.mstr_item_provision_ids
    , x.delivery_date
    , x.estimated_shipping_date
    , x.shipping_date
    , COUNT(*) AS shipping_detail_count
    , COUNT(*) FILTER (WHERE x.is_shipped AND x.shipping_date <= x.delivery_date) AS on_time_count
    , COUNT(*) FILTER (WHERE x.is_shipped AND x.shipping_date > x.delivery_date) AS late_count
    , COUNT(*) FILTER (WHERE NOT x.is_shipped AND x.delivery_date < CURRENT_DATE) AS overdue_count
    , COUNT(*) FILTER (WHERE NOT x.is_shipped AND (x.delivery_date >= CURRENT_DATE OR x.delivery_date IS NULL)) AS pending_count
    , COUNT(*) FILTER (WHERE x.is_shipped AND x.shipping_date <= x.estimated_shipping_date) AS schedule_kept_count
    , COUNT(*) FILTER (WHERE x.is_shipped AND x.shipping_date > x.estimated_shipping_date) AS schedule_missed_count
    , SUM(x.scheduled_quantity) AS scheduled_quantity
    , SUM(x.shipped_quantity) AS shipped_quantity
FROM
    (
        SELECT
            o.stakeholder_id AS customer_id
            , i.mstr_item_kind_id
            , i.mstr_item_id
            , pr.mstr_item_provision_ids
            , COALESCE(od.delivery_date, o.delivery_date)::DATE AS delivery_date
            , COALESCE(sd.estimated_shipping_date, so.estimated_shipping_date)::DATE AS estimated_shipping_date
            , rc.last_shipping_date::DATE AS shipping_date
            , sd.shipping_quantity AS scheduled_quantity
            , COALESCE(rc.shipped_quantity, 0) AS shipped_quantity
            , (COALESCE(rc.shipped_quantity, 0) >= sd.shipping_quantity) AS is_shipped
        FROM
            tests.trans_shipping_order_detail AS sd
            INNER JOIN tests.trans_shipping_order AS so
                ON so.trans_shipping_order_id = sd.trans_shipping_order_id
                AND so.remove IS FALSE
            INNER JOIN tests.trans_order_detail AS od
                ON od.trans_order_detail_id = sd.trans_order_detail_id
                AND od.remove IS FALSE
            INNER JOIN tests.trans_order AS o
                ON o.trans_order_id = od.trans_order_id
                AND o.remove IS FALSE
            INNER JOIN tests.mstr_stakeholder AS c
                ON c.mstr_stakeholder_id = o.stakeholder_id
                AND c.remove IS FALSE
            INNER JOIN tests.mstr_item AS i
                ON i.mstr_item_id = od.item_id
                AND i.remove IS FALSE
            INNER JOIN tests.mstr_item_kind AS k
                ON k.mstr_item_kind_id = i.mstr_item_kind_id
                AND k.remove IS FALSE
            LEFT JOIN LATERAL (
                SELECT
                    ARRAY_AGG(ip.mstr_item_provision_id ORDER BY ip.mstr_item_provision_id) AS mstr_item_provision_ids
                FROM
                    tests.mstr_item_provision AS ip
                    INNER JOIN tests.info_provision AS pv
                        ON pv.info_provision_id = ip.info_provision_id
                        AND pv.remove IS FALSE
                WHERE
                    ip.mstr_item_id = i.mstr_item_id
                    AND ip.remove IS FALSE
            ) AS pr
                ON TRUE
            LEFT JOIN LATERAL (
                SELECT
                    SUM(r.shipping_quantity) AS shipped_quantity
                    , MAX(r.shipping_date) AS last_shipping_date
                FROM
                    tests.trans_shipping_order_detail_record AS r
                WHERE
                    r.trans_shipping_order_detail_id = sd.trans_shipping_order_detail_id
                    AND r.remove IS FALSE
            ) AS rc
                ON TRUE
        WHERE
            sd.remove IS FALSE
    ) AS x
GROUP BY
    x.customer_id
    , x.mstr_item_kind_id
    , x.mstr_item_id
    , x.mstr_item_provision_ids
    , x.delivery_date
    , x.estimated_shipping_date
    , x.shipping_date;

COMMENT ON VIEW tests.v_shipping_delivery_compliance IS '@foreignKey (customer_id) references mstr_stakeholder (mstr_stakeholder_id)
@foreignKey (mstr_item_kind_id) references mstr_item_kind (mstr_item_kind_id)
@foreignKey (mstr_item_id) references mstr_item (mstr_item_id)
出荷納期遵守状況';

CREATE VIEW tests.v_shipping_order_status AS
SELECT
    o.stakeholder_id AS customer_id
    , i.mstr_item_kind_id
    , i.mstr_item_id
    , pr.mstr_item_provision_ids
    , COALESCE(od.delivery_date, o.delivery_date)::DATE AS delivery_date
    , COALESCE(sd.estimated_shipping_date, so.estimated_shipping_date)::DATE AS estimated_shipping_date
    , rc.last_shipping_date::DATE AS shipping_date
    , COUNT(sd.trans_shipping_order_detail_id) AS shipping_detail_count
    , COUNT(sd.trans_shipping_order_detail_id) FILTER (WHERE COALESCE(rc.shipped_quantity, 0) >= sd.shipping_quantity) AS shipped_detail_count
    , SUM(sd.shipping_quantity) AS scheduled_quantity
    , SUM(COALESCE(rc.shipped_quantity, 0)) AS shipped_quantity
    , SUM(GREATEST(sd.shipping_quantity - COALESCE(rc.shipped_quantity, 0), 0)) AS remaining_quantity
    , ROUND(SUM((sd.shipping_quantity) * COALESCE(od.fixed_price, od.unit_price, 0) + COALESCE(od.price_adjustment, 0) * COALESCE((sd.shipping_quantity) / NULLIF(od.quantity, 0), 0)), 2) AS scheduled_amount
    , ROUND(SUM((COALESCE(rc.shipped_quantity, 0)) * COALESCE(od.fixed_price, od.unit_price, 0) + COALESCE(od.price_adjustment, 0) * COALESCE((COALESCE(rc.shipped_quantity, 0)) / NULLIF(od.quantity, 0), 0)), 2) AS shipped_amount
FROM
    tests.trans_shipping_order_detail AS sd
    INNER JOIN tests.trans_shipping_order AS so
        ON so.trans_shipping_order_id = sd.trans_shipping_order_id
        AND so.remove IS FALSE
    INNER JOIN tests.trans_order_detail AS od
        ON od.trans_order_detail_id = sd.trans_order_detail_id
        AND od.remove IS FALSE
    INNER JOIN tests.trans_order AS o
        ON o.trans_order_id = od.trans_order_id
        AND o.remove IS FALSE
    INNER JOIN tests.mstr_stakeholder AS c
        ON c.mstr_stakeholder_id = o.stakeholder_id
        AND c.remove IS FALSE
    INNER JOIN tests.mstr_item AS i
        ON i.mstr_item_id = od.item_id
        AND i.remove IS FALSE
    INNER JOIN tests.mstr_item_kind AS k
        ON k.mstr_item_kind_id = i.mstr_item_kind_id
        AND k.remove IS FALSE
    LEFT JOIN LATERAL (
        SELECT
            ARRAY_AGG(ip.mstr_item_provision_id ORDER BY ip.mstr_item_provision_id) AS mstr_item_provision_ids
        FROM
            tests.mstr_item_provision AS ip
            INNER JOIN tests.info_provision AS pv
                ON pv.info_provision_id = ip.info_provision_id
                AND pv.remove IS FALSE
        WHERE
            ip.mstr_item_id = i.mstr_item_id
            AND ip.remove IS FALSE
    ) AS pr
        ON TRUE
    LEFT JOIN LATERAL (
        SELECT
            SUM(r.shipping_quantity) AS shipped_quantity
            , MAX(r.shipping_date) AS last_shipping_date
        FROM
            tests.trans_shipping_order_detail_record AS r
        WHERE
            r.trans_shipping_order_detail_id = sd.trans_shipping_order_detail_id
            AND r.remove IS FALSE
    ) AS rc
        ON TRUE
WHERE
    sd.remove IS FALSE
GROUP BY
    o.stakeholder_id
    , i.mstr_item_kind_id
    , i.mstr_item_id
    , pr.mstr_item_provision_ids
    , COALESCE(od.delivery_date, o.delivery_date)::DATE
    , COALESCE(sd.estimated_shipping_date, so.estimated_shipping_date)::DATE
    , rc.last_shipping_date::DATE;

COMMENT ON VIEW tests.v_shipping_order_status IS '@foreignKey (customer_id) references mstr_stakeholder (mstr_stakeholder_id)
@foreignKey (mstr_item_kind_id) references mstr_item_kind (mstr_item_kind_id)
@foreignKey (mstr_item_id) references mstr_item (mstr_item_id)
出荷予定受注実績状況';

CREATE VIEW tests.v_purchase_delivery_compliance AS
SELECT
    x.supplier_id
    , x.mstr_item_kind_id
    , x.mstr_item_id
    , x.mstr_item_provision_ids
    , x.period
    , x.is_received
    , COUNT(*) AS purchase_detail_count
    , COUNT(*) FILTER (WHERE x.is_received AND x.received_date <= x.period) AS on_time_count
    , COUNT(*) FILTER (WHERE x.is_received AND x.received_date > x.period) AS late_count
    , COUNT(*) FILTER (WHERE NOT x.is_received AND x.period < CURRENT_DATE) AS overdue_count
    , COUNT(*) FILTER (WHERE NOT x.is_received AND (x.period >= CURRENT_DATE OR x.period IS NULL)) AS pending_count
    , SUM(x.purchase_quantity) AS purchase_quantity
    , SUM(x.received_quantity) AS received_quantity
FROM
    (
        SELECT
            p.stakeholder_id AS supplier_id
            , i.mstr_item_kind_id
            , i.mstr_item_id
            , pr.mstr_item_provision_ids
            , pd.period::DATE AS period
            , COALESCE(pd.quantity, 0) AS purchase_quantity
            , COALESCE(rc.received_quantity, 0) AS received_quantity
            , (COALESCE(rc.received_quantity, 0) >= COALESCE(pd.quantity, 0)) AS is_received
            , rc.last_receive_at::DATE AS received_date
        FROM
            tests.trans_purchase_detail AS pd
            INNER JOIN tests.trans_purchase AS p
                ON p.trans_purchase_id = pd.trans_purchase_id
                AND p.remove IS FALSE
            INNER JOIN tests.mstr_stakeholder AS s
                ON s.mstr_stakeholder_id = p.stakeholder_id
                AND s.remove IS FALSE
            INNER JOIN tests.mstr_item AS i
                ON i.mstr_item_id = pd.item_id
                AND i.remove IS FALSE
            INNER JOIN tests.mstr_item_kind AS k
                ON k.mstr_item_kind_id = i.mstr_item_kind_id
                AND k.remove IS FALSE
            LEFT JOIN LATERAL (
                SELECT
                    ARRAY_AGG(ip.mstr_item_provision_id ORDER BY ip.mstr_item_provision_id) AS mstr_item_provision_ids
                FROM
                    tests.mstr_item_provision AS ip
                    INNER JOIN tests.info_provision AS pv
                        ON pv.info_provision_id = ip.info_provision_id
                        AND pv.remove IS FALSE
                WHERE
                    ip.mstr_item_id = i.mstr_item_id
                    AND ip.remove IS FALSE
            ) AS pr
                ON TRUE
            LEFT JOIN LATERAL (
                SELECT
                    SUM(r.quantity) AS received_quantity
                    , MAX(r.receive_at) AS last_receive_at
                FROM
                    tests.trans_purchase_rec AS r
                WHERE
                    r.trans_purchase_detail_id = pd.trans_purchase_detail_id
                    AND r.remove IS FALSE
            ) AS rc
                ON TRUE
        WHERE
            pd.remove IS FALSE
    ) AS x
GROUP BY
    x.supplier_id
    , x.mstr_item_kind_id
    , x.mstr_item_id
    , x.mstr_item_provision_ids
    , x.period
    , x.is_received;

COMMENT ON VIEW tests.v_purchase_delivery_compliance IS '@foreignKey (supplier_id) references mstr_stakeholder (mstr_stakeholder_id)
@foreignKey (mstr_item_kind_id) references mstr_item_kind (mstr_item_kind_id)
@foreignKey (mstr_item_id) references mstr_item (mstr_item_id)
発注納期遵守状況';

CREATE VIEW tests.v_staff_effective_access_path AS
WITH src AS (
    -- 所属部署から継承 (有効な所属のみ。上位部署からは継承しない) : 読み取り + 書き込みフラグ
    SELECT a.info_staff_id, d.info_access_path_id, COALESCE(d.write, FALSE) AS can_write, TRUE AS from_department, FALSE AS from_staff
    FROM tests.info_assign AS a
    INNER JOIN tests.info_department AS dp
        ON dp.info_department_id = a.info_department_id AND dp.remove IS FALSE
    INNER JOIN tests.info_department_access_path AS d
        ON d.info_department_id = a.info_department_id AND d.remove IS FALSE
    WHERE a.enable IS TRUE AND a.remove IS FALSE
    UNION ALL
    -- 担当者ごとの許可 : 読み取り + 書き込みフラグ
    SELECT p.info_staff_id, p.info_access_path_id, COALESCE(p.write, FALSE), FALSE, TRUE
    FROM tests.info_staff_access_permission AS p
    WHERE p.remove IS FALSE
)
SELECT
    s.info_staff_id
    , st.symbol AS staff_symbol
    , st.code AS staff_code
    , s.info_access_path_id
    , ap.symbol AS access_path_symbol
    , ap.usecase_path
    , ap.info_app_id
    , BOOL_OR(s.can_write) AS can_write
    , BOOL_OR(s.from_department) AS from_department
    , BOOL_OR(s.from_staff) AS from_staff
FROM src AS s
INNER JOIN tests.info_staff AS st ON st.info_staff_id = s.info_staff_id AND st.remove IS FALSE
INNER JOIN tests.info_access_path AS ap ON ap.info_access_path_id = s.info_access_path_id AND ap.remove IS FALSE
GROUP BY s.info_staff_id, st.symbol, st.code, s.info_access_path_id, ap.symbol, ap.usecase_path, ap.info_app_id;

COMMENT ON VIEW tests.v_staff_effective_access_path IS '@primaryKey info_staff_id,info_access_path_id
@foreignKey (info_staff_id) references info_staff (info_staff_id)
@foreignKey (info_access_path_id) references info_access_path (info_access_path_id)
@foreignKey (info_app_id) references info_app (info_app_id)
担当者の実効アクセスパス(所属部署から継承した権限＋担当者ごとの許可)';

CREATE VIEW tests.v_purchase_amount AS
SELECT
    p.stakeholder_id AS supplier_id
    , i.mstr_item_kind_id
    , i.mstr_item_id
    , pr.mstr_item_provision_ids
    , pd.period::DATE AS period
    , (COALESCE(rc.received_quantity, 0) >= COALESCE(pd.quantity, 0)) AS is_received
    , COUNT(pd.trans_purchase_detail_id) AS purchase_detail_count
    , SUM(COALESCE(pd.quantity, 0)) AS purchase_quantity
    , SUM(COALESCE(rc.received_quantity, 0)) AS received_quantity
    , SUM(COALESCE(pd.quantity, 0) * COALESCE(pd.fixed_price, pd.unit_price, 0) + COALESCE(pd.price_adjustment, 0)) AS purchase_amount
    , ROUND(SUM((COALESCE(rc.received_quantity, 0)) * COALESCE(pd.fixed_price, pd.unit_price, 0) + COALESCE(pd.price_adjustment, 0) * COALESCE((COALESCE(rc.received_quantity, 0)) / NULLIF(pd.quantity, 0), 0)), 2) AS received_amount
FROM
    tests.trans_purchase_detail AS pd
    INNER JOIN tests.trans_purchase AS p
        ON p.trans_purchase_id = pd.trans_purchase_id
        AND p.remove IS FALSE
    INNER JOIN tests.mstr_stakeholder AS s
        ON s.mstr_stakeholder_id = p.stakeholder_id
        AND s.remove IS FALSE
    INNER JOIN tests.mstr_item AS i
        ON i.mstr_item_id = pd.item_id
        AND i.remove IS FALSE
    INNER JOIN tests.mstr_item_kind AS k
        ON k.mstr_item_kind_id = i.mstr_item_kind_id
        AND k.remove IS FALSE
    LEFT JOIN LATERAL (
        SELECT
            ARRAY_AGG(ip.mstr_item_provision_id ORDER BY ip.mstr_item_provision_id) AS mstr_item_provision_ids
        FROM
            tests.mstr_item_provision AS ip
            INNER JOIN tests.info_provision AS pv
                ON pv.info_provision_id = ip.info_provision_id
                AND pv.remove IS FALSE
        WHERE
            ip.mstr_item_id = i.mstr_item_id
            AND ip.remove IS FALSE
    ) AS pr
        ON TRUE
    LEFT JOIN LATERAL (
        SELECT
            SUM(r.quantity) AS received_quantity
        FROM
            tests.trans_purchase_rec AS r
        WHERE
            r.trans_purchase_detail_id = pd.trans_purchase_detail_id
            AND r.remove IS FALSE
    ) AS rc
        ON TRUE
WHERE
    pd.remove IS FALSE
GROUP BY
    p.stakeholder_id
    , i.mstr_item_kind_id
    , i.mstr_item_id
    , pr.mstr_item_provision_ids
    , pd.period::DATE
    , (COALESCE(rc.received_quantity, 0) >= COALESCE(pd.quantity, 0));

COMMENT ON VIEW tests.v_purchase_amount IS '@foreignKey (supplier_id) references mstr_stakeholder (mstr_stakeholder_id)
@foreignKey (mstr_item_kind_id) references mstr_item_kind (mstr_item_kind_id)
@foreignKey (mstr_item_id) references mstr_item (mstr_item_id)
発注金額合計';

CREATE VIEW tests.v_sales_record AS
SELECT
    o.stakeholder_id AS customer_id
    , i.mstr_item_kind_id
    , i.mstr_item_id
    , pr.mstr_item_provision_ids
    , COALESCE(od.delivery_date, o.delivery_date)::DATE AS delivery_date
    , (COALESCE(sh.shipped_quantity, 0) >= od.quantity - od.cancel_quantity) AS is_shipped
    , COUNT(od.trans_order_detail_id) AS order_detail_count
    , SUM(od.quantity - od.cancel_quantity) AS order_quantity
    , SUM(od.cancel_quantity) AS cancel_quantity
    , SUM(COALESCE(sh.shipped_quantity, 0)) AS shipped_quantity
    , SUM(COALESCE(od.quantity - od.cancel_quantity, 0) * COALESCE(od.fixed_price, od.unit_price, 0) + COALESCE(od.price_adjustment, 0)) AS order_amount
    , ROUND(SUM((COALESCE(sh.shipped_quantity, 0)) * COALESCE(od.fixed_price, od.unit_price, 0) + COALESCE(od.price_adjustment, 0) * COALESCE((COALESCE(sh.shipped_quantity, 0)) / NULLIF(od.quantity - od.cancel_quantity, 0), 0)), 2) AS shipped_amount
    , SUM(COALESCE(st.settlement_amount, 0)) AS settlement_amount
    , SUM(COALESCE(od.quantity - od.cancel_quantity, 0) * COALESCE(od.fixed_price, od.unit_price, 0) + COALESCE(od.price_adjustment, 0)
          + COALESCE(st.settlement_amount, 0)) AS total_amount
FROM
    tests.trans_order_detail AS od
    INNER JOIN tests.trans_order AS o
        ON o.trans_order_id = od.trans_order_id
        AND o.remove IS FALSE
    INNER JOIN tests.mstr_stakeholder AS c
        ON c.mstr_stakeholder_id = o.stakeholder_id
        AND c.remove IS FALSE
    INNER JOIN tests.mstr_item AS i
        ON i.mstr_item_id = od.item_id
        AND i.remove IS FALSE
    INNER JOIN tests.mstr_item_kind AS k
        ON k.mstr_item_kind_id = i.mstr_item_kind_id
        AND k.remove IS FALSE
    LEFT JOIN LATERAL (
        SELECT
            ARRAY_AGG(ip.mstr_item_provision_id ORDER BY ip.mstr_item_provision_id) AS mstr_item_provision_ids
        FROM
            tests.mstr_item_provision AS ip
            INNER JOIN tests.info_provision AS pv
                ON pv.info_provision_id = ip.info_provision_id
                AND pv.remove IS FALSE
        WHERE
            ip.mstr_item_id = i.mstr_item_id
            AND ip.remove IS FALSE
    ) AS pr
        ON TRUE
    LEFT JOIN LATERAL (
        SELECT
            SUM(r.shipping_quantity) AS shipped_quantity
        FROM
            tests.trans_shipping_order_detail AS sd
            INNER JOIN tests.trans_shipping_order AS so
                ON so.trans_shipping_order_id = sd.trans_shipping_order_id
                AND so.remove IS FALSE
            INNER JOIN tests.trans_shipping_order_detail_record AS r
                ON r.trans_shipping_order_detail_id = sd.trans_shipping_order_detail_id
                AND r.remove IS FALSE
        WHERE
            sd.trans_order_detail_id = od.trans_order_detail_id
            AND sd.remove IS FALSE
    ) AS sh
        ON TRUE
    LEFT JOIN LATERAL (
        SELECT
            SUM(s.amount) AS settlement_amount
        FROM
            tests.trans_order_detail_settlement AS s
        WHERE
            s.trans_order_detail_id = od.trans_order_detail_id
            AND s.remove IS FALSE
    ) AS st
        ON TRUE
WHERE
    od.remove IS FALSE
GROUP BY
    o.stakeholder_id
    , i.mstr_item_kind_id
    , i.mstr_item_id
    , pr.mstr_item_provision_ids
    , COALESCE(od.delivery_date, o.delivery_date)::DATE
    , (COALESCE(sh.shipped_quantity, 0) >= od.quantity - od.cancel_quantity);

COMMENT ON VIEW tests.v_sales_record IS '@foreignKey (customer_id) references mstr_stakeholder (mstr_stakeholder_id)
@foreignKey (mstr_item_kind_id) references mstr_item_kind (mstr_item_kind_id)
@foreignKey (mstr_item_id) references mstr_item (mstr_item_id)
売り上げ実績';

CREATE VIEW tests.v_staff_count AS
SELECT
    d.info_company_id
    , a.info_department_id
    , a.info_position_id
    , COUNT(DISTINCT a.info_staff_id) AS staff_count
    , COUNT(a.info_assign_id) AS assign_count
FROM
    tests.info_assign AS a
    INNER JOIN tests.info_staff AS s
        ON s.info_staff_id = a.info_staff_id
        AND s.remove IS FALSE
    INNER JOIN tests.info_department AS d
        ON d.info_department_id = a.info_department_id
        AND d.remove IS FALSE
    INNER JOIN tests.info_position AS p
        ON p.info_position_id = a.info_position_id
        AND p.remove IS FALSE
WHERE
    a.remove IS FALSE
    AND a.enable IS TRUE
GROUP BY
    d.info_company_id
    , a.info_department_id
    , a.info_position_id;

