CREATE VIEW tests.v_visiter_item AS
-- 在庫(ロット)の品目 (issue 20261107_0009 B案)
-- 分割・移動した在庫は、分割元をたどった最初の在庫(root_visiter_id)の
-- 受入実績(発注明細の品目)・作業実績(生産計画 → 資材計画の品目)・支給・返品(明細の品目)で決める。
SELECT
    l.trans_visiter_id
    , l.symbol
    , COALESCE(pd.item_id, rp.item_id, sp.item_id, rt.item_id) AS mstr_item_id
FROM tests.v_visiter_lot AS l
LEFT JOIN LATERAL (
    -- 受入実績(購入品)の品目
    SELECT d.item_id
    FROM tests.trans_purchase_rec_visiter AS prv
    INNER JOIN tests.trans_purchase_rec AS pr
        ON pr.trans_purchase_rec_id = prv.trans_purchase_rec_id AND pr.remove IS FALSE
    INNER JOIN tests.trans_purchase_detail AS d
        ON d.trans_purchase_detail_id = pr.trans_purchase_detail_id
    WHERE prv.trans_visiter_id = COALESCE(l.root_visiter_id, l.trans_visiter_id)
    LIMIT 1
) AS pd ON TRUE
LEFT JOIN LATERAL (
    -- 作業実績(製造品)の品目
    SELECT r.item_id
    FROM tests.trans_work_record_visiter AS wrv
    INNER JOIN tests.trans_work_record AS wr
        ON wr.trans_work_record_id = wrv.trans_work_record_id AND wr.remove IS FALSE
    INNER JOIN tests.trans_work_plan AS wp
        ON wp.trans_work_plan_id = wr.trans_work_plan_id
    INNER JOIN tests.trans_operations_plan AS op
        ON op.trans_operations_plan_id = wp.trans_operations_plan_id
    INNER JOIN tests.trans_resource_plan AS r
        ON r.trans_resource_plan_id = op.trans_resource_plan_id
    WHERE wrv.trans_visiter_id = COALESCE(l.root_visiter_id, l.trans_visiter_id)
    LIMIT 1
) AS rp ON TRUE
LEFT JOIN LATERAL (
    -- 支給で入庫した在庫(顧客支給材・発注先からの戻り)の品目  claude/131
    SELECT d.item_id
    FROM tests.trans_supply_visiter AS sv
    INNER JOIN tests.trans_supply_detail AS d
        ON d.trans_supply_detail_id = sv.trans_supply_detail_id AND d.remove IS FALSE
    WHERE sv.trans_visiter_id = COALESCE(l.root_visiter_id, l.trans_visiter_id) AND sv.remove IS FALSE
    LIMIT 1
) AS sp ON TRUE
LEFT JOIN LATERAL (
    -- 返品で入庫した在庫(顧客からの返品)の品目  claude/131
    SELECT d.item_id
    FROM tests.trans_return_visiter AS rv
    INNER JOIN tests.trans_return_detail AS d
        ON d.trans_return_detail_id = rv.trans_return_detail_id AND d.remove IS FALSE
    WHERE rv.trans_visiter_id = COALESCE(l.root_visiter_id, l.trans_visiter_id) AND rv.remove IS FALSE
    LIMIT 1
) AS rt ON TRUE;

COMMENT ON VIEW tests.v_visiter_item IS '@primaryKey trans_visiter_id
@unique symbol
@foreignKey (trans_visiter_id) references trans_visiter (trans_visiter_id)
@foreignKey (mstr_item_id) references mstr_item (mstr_item_id)
在庫(ロット)の品目';

