CREATE VIEW tests.v_external_property AS
-- 社外の所有物 (顧客・発注先。ISO 9001 8.5.3 の所有物一覧)  claude/131
-- 今の数量が残っている在庫(ロット)のうち、有効な所有者(trans_visiter_owner)が自社ではないもの
SELECT
    o.trans_visiter_id
    , l.symbol
    , o.owner_stakeholder_id
    , o.owner_stakeholder_history_id
    , vi.item_id
    , l.trans_container_id
    , l.mstr_location_id
    , l.quantity
    , l.release
    , l.open_complaint_count
    , o.trans_supply_detail_id
    , o.trans_order_detail_id
    , o.effective_at
FROM tests.trans_visiter_owner AS o
INNER JOIN tests.v_visiter_lot AS l ON l.trans_visiter_id = o.trans_visiter_id
LEFT JOIN tests.v_mrp_visiter_item AS vi ON vi.trans_visiter_id = o.trans_visiter_id
WHERE o.remove IS FALSE AND o.owner_stakeholder_id IS NOT NULL AND l.quantity > 0;

COMMENT ON VIEW tests.v_external_property IS '@primaryKey trans_visiter_id
@unique symbol
@foreignKey (trans_visiter_id) references trans_visiter (trans_visiter_id)
@foreignKey (owner_stakeholder_id) references mstr_stakeholder (mstr_stakeholder_id)
@foreignKey (item_id) references mstr_item (mstr_item_id)
@foreignKey (trans_container_id) references trans_container (trans_container_id)
@foreignKey (trans_supply_detail_id) references trans_supply_detail (trans_supply_detail_id)
@foreignKey (trans_order_detail_id) references trans_order_detail (trans_order_detail_id)
社外の所有物(顧客・発注先)';

