            NEW.mstr_equipment_category_id,
            NEW.code,
            NEW.control_code,
            NEW.label_code,
            NEW.mstr_location_id,
            NEW.revision,
            NEW.symbol,
            NEW.remarks,
            NEW.update_at,
            NEW.update_user_id,
            NEW.update_user_history_id,
            NEW.remove
        );
        RETURN NEW;
    ELSEIF (TG_OP = 'DELETE') THEN
