CREATE OR REPLACE FUNCTION tests.trg_02_history_mstr_license() RETURNS trigger AS
$BODY$
DECLARE
    revisions int;
BEGIN
    IF (TG_OP = 'UPDATE') OR (TG_OP='INSERT') THEN
        SELECT Max(revision) INTO revisions FROM tests.history_mstr_license WHERE mstr_license_id=NEW.mstr_license_id;
        IF (revisions >= 0) THEN
            IF (
                NEW.mstr_license_id,
                NEW.code,
                NEW.names,
                NEW.details,
                NEW.public_license,
                NEW.customer_license,
                NEW.organization_license,
                NEW.update_interval,
                NEW.symbol,
                NEW.remarks,
                NEW.remove
            ) IS NOT DISTINCT FROM (
                OLD.mstr_license_id,
                OLD.code,
                OLD.names,
                OLD.details,
                OLD.public_license,
                OLD.customer_license,
                OLD.organization_license,
                OLD.update_interval,
                OLD.symbol,
                OLD.remarks,
                OLD.remove
            )
            THEN
                RETURN NULL;
            END IF;
            NEW.revision := revisions + 1;
        ELSE
            NEW.revision := 1;
        END IF;
        INSERT INTO tests.history_mstr_license (
            mstr_license_id,
            code,
            names,
            details,
            public_license,
            customer_license,
            organization_license,
            update_interval,
            revision,
            symbol,
            remarks,
            update_at,
            update_user_id,
            update_user_history_id,
            remove
        )
        VALUES
        (
            NEW.mstr_license_id,
            NEW.code,
            NEW.names,
            NEW.details,
            NEW.public_license,
            NEW.customer_license,
            NEW.organization_license,
            NEW.update_interval,
            NEW.revision,
            NEW.symbol,
            NEW.remarks,
            NEW.update_at,
            NEW.update_user_id,
            NEW.update_user_history_id,
            NEW.remove
        );
        RETURN NEW;
    ELSEIF (TG_OP = 'DELETE') THEN
        RETURN OLD;
    END IF;
END
$BODY$
LANGUAGE plpgsql VOLATILE;

